async function queuedDeleteMessageWithAck(sock, jid, messageKey, delayMs = 120, timeoutMs = 6500) {
    if (!sock?.ev || typeof sock.ev.on !== 'function') throw new Error('whatsapp_delete_ack_listener_unavailable');
    const destination = String(jid || '').trim();
    const messageId = String(messageKey?.id || '').trim();
    const remoteJid = String(messageKey?.remoteJid || destination).trim();
    const participant = String(messageKey?.participant || messageKey?.participantPn || messageKey?.participantAlt || messageKey?.senderPn || '').trim();
    if (!destination || !messageId || !remoteJid) throw new Error('whatsapp_delete_target_key_incomplete');
    if (/@g\.us$/i.test(remoteJid) && !messageKey?.fromMe && !participant) throw new Error('whatsapp_group_delete_participant_missing');
    const normalizedKey = {
        ...messageKey,
        remoteJid,
        id: messageId,
        fromMe: messageKey?.fromMe === true
    };
    if (participant) normalizedKey.participant = participant;
    let sentMessageId = '';
    let matchedUpdate = null;
    const earlyUpdates = [];
    let resolveAck;
    const ackPromise = new Promise(resolve => { resolveAck = resolve; });
    const isServerAcknowledgement = update => {
        if (update?.error) return true;
        const status = Number(update?.status);
        return Number.isFinite(status) && status >= 2 && status <= 5;
    };
    const listener = updates => {
        for (const item of Array.isArray(updates) ? updates : []) {
            const updateId = String(item?.key?.id || '');
            if (!updateId) continue;
            const update = item?.update || {};
            if (sentMessageId && updateId === sentMessageId) {
                if (isServerAcknowledgement(update)) {
                    matchedUpdate = update;
                    resolveAck(update);
                }
            } else {
                earlyUpdates.push(item);
                if (earlyUpdates.length > 150) earlyUpdates.shift();
            }
        }
    };
    sock.ev.on('messages.update', listener);
    try {
        const sent = await queuedSendMessage(sock, destination, { delete: normalizedKey }, {}, delayMs);
        sentMessageId = String(sent?.key?.id || '');
        if (!sentMessageId) throw new Error('whatsapp_delete_message_id_missing');
        const early = earlyUpdates.find(item => String(item?.key?.id || '') === sentMessageId && isServerAcknowledgement(item?.update || {}));
        if (early) {
            matchedUpdate = early.update || {};
            resolveAck(matchedUpdate);
        }
        const acknowledgement = matchedUpdate || await promiseWithTimeout(ackPromise, timeoutMs, 'WhatsApp server delete acknowledgement');
        const status = Number(acknowledgement?.status);
        if (acknowledgement?.error || !Number.isFinite(status) || status < 2 || status > 5) {
            const reason = acknowledgement?.error?.message || `status_${String(acknowledgement?.status ?? 'missing')}`;
            throw new Error(`whatsapp_delete_not_confirmed:${reason}`);
        }
        return { sent, acknowledgement, confirmed: true, target: normalizedKey, acknowledgementStatus: status };
    } finally {
        try {
            if (typeof sock.ev.off === 'function') sock.ev.off('messages.update', listener);
            else if (typeof sock.ev.removeListener === 'function') sock.ev.removeListener('messages.update', listener);
        } catch (error) {}
    }
}

function getMessageRetryCount(key) {
    const normalizedKey = String(key || '');
    const expiresAt = Number(msgRetryCounterExpiryCache.get(normalizedKey) || 0);
    if (!expiresAt || expiresAt <= Date.now()) {
        msgRetryCounterCache.delete(normalizedKey);
        msgRetryCounterExpiryCache.delete(normalizedKey);
        return undefined;
    }
    return msgRetryCounterCache.get(normalizedKey);
}

function setMessageRetryCount(key, value, ttlSeconds) {
    const normalizedKey = String(key || '');
    if (!normalizedKey) return value;
    const requestedTtl = Number(ttlSeconds);
    const ttlMs = requestedTtl > 0 ? Math.min(86400000, requestedTtl * 1000) : MSG_RETRY_COUNTER_TTL_MS;
    msgRetryCounterCache.set(normalizedKey, value);
    msgRetryCounterExpiryCache.set(normalizedKey, Date.now() + ttlMs);
    if (msgRetryCounterCache.size > MSG_RETRY_COUNTER_MAX_ENTRIES) {
        const now = Date.now();
        for (const [storedKey, storedExpiry] of msgRetryCounterExpiryCache.entries()) {
            if (storedExpiry <= now || msgRetryCounterCache.size > MSG_RETRY_COUNTER_MAX_ENTRIES) {
                msgRetryCounterCache.delete(storedKey);
                msgRetryCounterExpiryCache.delete(storedKey);
            }
        }
    }
    return value;
}

function deleteMessageRetryCount(key) {
    const normalizedKey = String(key || '');
    msgRetryCounterExpiryCache.delete(normalizedKey);
    return msgRetryCounterCache.delete(normalizedKey);
}

function createSessionRetryCache(sessionId) {
    const prefix = `${String(sessionId || 'default')}:`;
    const keyFor = key => `${prefix}${String(key || '')}`;
    return {
        get: key => getMessageRetryCount(keyFor(key)),
        set: (key, value, ttlSeconds) => setMessageRetryCount(keyFor(key), value, ttlSeconds),
        del: key => deleteMessageRetryCount(keyFor(key)),
        delete: key => deleteMessageRetryCount(keyFor(key)),
        clear: () => {
            for (const key of msgRetryCounterCache.keys()) {
                if (key.startsWith(prefix)) {
                    msgRetryCounterCache.delete(key);
                    msgRetryCounterExpiryCache.delete(key);
                }
            }
        }
    };
}

const TFBOT_DATABASE_NAME = 'tfbot';
const TFBOT_APP_DATA_COLLECTION = 'tfbot_data';
const TFBOT_WHATSAPP_COLLECTION = 'whatsapp_sessions';
const TFBOT_LOGICAL_COLLECTIONS = new Set([
    'baileys_outgoing_messages',
    'baileys_quoted_messages',
    'cluster_instances',
    'cluster_router',
    'bot_runtime_state',
    'group_del2',
    'group_del3',
    'group_settings',
    'lid_phone_mappings',
    'processed_messages',
    'session_account_runtime_locks',
    'session_owners',
    'session_runtime_locks',
    'user_preferences'
]);

function cloneMongoValue(value) {
    if (value === null || value === undefined || typeof value !== 'object') return value;
    if (Buffer.isBuffer(value)) return Buffer.from(value);
    if (value instanceof Uint8Array) return Buffer.from(value);
    if (value instanceof Date) return new Date(value.getTime());
    if (value instanceof RegExp) return new RegExp(value.source, value.flags);
    if (Array.isArray(value)) return value.map(cloneMongoValue);
    const prototype = Object.getPrototypeOf(value);
    if (prototype !== Object.prototype && prototype !== null) return value;
    const output = Object.create(prototype);
    for (const [key, item] of Object.entries(value)) output[key] = cloneMongoValue(item);
    return output;
}

function tfbotNamespacedId(bucket, value) {
    if (typeof value !== 'string') return value;
    const prefix = `${bucket}::`;
    return value.startsWith(prefix) ? value : `${prefix}${value}`;
}

function tfbotOriginalId(bucket, value) {
    if (typeof value !== 'string') return value;
    const prefix = `${bucket}::`;
    return value.startsWith(prefix) ? value.slice(prefix.length) : value;
}

function tfbotEscapeRegex(value) {
    return String(value).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function tfbotRewriteIdCondition(value, bucket) {
    if (typeof value === 'string') return tfbotNamespacedId(bucket, value);
    if (Array.isArray(value)) return value.map(item => tfbotRewriteIdCondition(item, bucket));
    if (!value || typeof value !== 'object' || value instanceof Date || value instanceof RegExp || Buffer.isBuffer(value)) return value;
    const output = {};
    for (const [operator, operand] of Object.entries(value)) {
        if (['$in', '$nin', '$all'].includes(operator) && Array.isArray(operand)) {
            output[operator] = operand.map(item => tfbotRewriteIdCondition(item, bucket));
        } else if (['$eq', '$ne', '$gt', '$gte', '$lt', '$lte'].includes(operator) && typeof operand === 'string') {
            output[operator] = tfbotNamespacedId(bucket, operand);
        } else if (operator === '$regex') {
            if (operand instanceof RegExp) {
                const source = operand.source.replace(/^\^/, '');
                output[operator] = new RegExp(`^${tfbotEscapeRegex(bucket)}::${source}`, operand.flags);
            } else {
                const source = String(operand || '').replace(/^\^/, '');
                output[operator] = `^${tfbotEscapeRegex(bucket)}::${source}`;
            }
        } else if (operator === '$not') {
            output[operator] = tfbotRewriteIdCondition(operand, bucket);
        } else {
            output[operator] = cloneMongoValue(operand);
        }
    }
    return output;
}

function tfbotRewriteFilter(filter, bucket) {
    const source = filter && typeof filter === 'object' ? filter : {};
    const output = {};
    for (const [key, value] of Object.entries(source)) {
        if (key === '_id') output._id = tfbotRewriteIdCondition(value, bucket);
        else if (['$or', '$and', '$nor'].includes(key) && Array.isArray(value)) output[key] = value.map(item => tfbotRewriteFilter(item, bucket));
        else output[key] = cloneMongoValue(value);
    }
    output.__tfbotBucket = bucket;
    return output;
}

function tfbotPrepareDocument(document, bucket) {
    const output = cloneMongoValue(document || {});
    if (typeof output._id === 'string') output._id = tfbotNamespacedId(bucket, output._id);
    output.__tfbotBucket = bucket;
    if (bucket === 'baileys_outgoing_messages' && output.createdAt) {
        const createdAt = new Date(output.createdAt).getTime();
        if (Number.isFinite(createdAt)) output.__tfbotExpiresAt = new Date(createdAt + BAILEYS_RETRY_MESSAGE_TTL_SECONDS * 1000);
    }
    return output;
}

function tfbotPrepareUpdate(update, bucket) {
    if (!update || typeof update !== 'object') return update;
    const output = cloneMongoValue(update);
    const hasOperator = Object.keys(output).some(key => key.startsWith('$'));
    if (!hasOperator) return tfbotPrepareDocument(output, bucket);
    const cleanBucketPath = fields => {
        if (!fields || typeof fields !== 'object' || Array.isArray(fields)) return;
        for (const key of Object.keys(fields)) {
            if (key === '__tfbotBucket' || key.startsWith('__tfbotBucket.')) delete fields[key];
        }
    };
    const setFields = output.$set && typeof output.$set === 'object' && !Array.isArray(output.$set) ? output.$set : null;
    const insertFields = output.$setOnInsert && typeof output.$setOnInsert === 'object' && !Array.isArray(output.$setOnInsert) ? output.$setOnInsert : null;
    for (const fields of [setFields, insertFields]) {
        if (!fields) continue;
        if (typeof fields._id === 'string') fields._id = tfbotNamespacedId(bucket, fields._id);
        if (bucket === 'baileys_outgoing_messages' && fields.createdAt) {
            const createdAt = new Date(fields.createdAt).getTime();
            if (Number.isFinite(createdAt)) fields.__tfbotExpiresAt = new Date(createdAt + BAILEYS_RETRY_MESSAGE_TTL_SECONDS * 1000);
        }
        cleanBucketPath(fields);
    }
    const bucketFields = setFields || insertFields || (output.$setOnInsert = {});
    bucketFields.__tfbotBucket = bucket;
    for (const [operator, fields] of Object.entries(output)) {
        if (!operator.startsWith('$') || !fields || typeof fields !== 'object' || Array.isArray(fields)) continue;
        if (fields !== bucketFields) cleanBucketPath(fields);
    }
    return output;
}

function tfbotRestoreDocument(document, bucket) {
    if (!document || typeof document !== 'object') return document;
    const output = cloneMongoValue(document);
    if (Object.prototype.hasOwnProperty.call(output, '_id')) output._id = tfbotOriginalId(bucket, output._id);
    delete output.__tfbotBucket;
    delete output.__tfbotExpiresAt;
    return output;
}

class TfbotLogicalCursor {
    constructor(cursor, bucket) {
        this.cursor = cursor;
        this.bucket = bucket;
    }
    sort(value) { this.cursor.sort(value); return this; }
    limit(value) { this.cursor.limit(value); return this; }
    skip(value) { this.cursor.skip(value); return this; }
    project(value) { this.cursor.project(value); return this; }
    batchSize(value) { this.cursor.batchSize(value); return this; }
    maxTimeMS(value) { if (typeof this.cursor.maxTimeMS === 'function') this.cursor.maxTimeMS(value); return this; }
    async toArray() { return (await this.cursor.toArray()).map(item => tfbotRestoreDocument(item, this.bucket)); }
    async next() { return tfbotRestoreDocument(await this.cursor.next(), this.bucket); }
    async hasNext() { return this.cursor.hasNext(); }
    async close() { return this.cursor.close(); }
}

class TfbotLogicalCollection {
    constructor(rawCollection, bucket) {
        this.rawCollection = rawCollection;
        this.bucket = bucket;
        this.collectionName = bucket;
    }
    find(filter = {}, options = {}) {
        return new TfbotLogicalCursor(this.rawCollection.find(tfbotRewriteFilter(filter, this.bucket), options), this.bucket);
    }
    async findOne(filter = {}, options = {}) {
        return tfbotRestoreDocument(await this.rawCollection.findOne(tfbotRewriteFilter(filter, this.bucket), options), this.bucket);
    }
    async updateOne(filter, update, options = {}) {
        return this.rawCollection.updateOne(tfbotRewriteFilter(filter, this.bucket), tfbotPrepareUpdate(update, this.bucket), options);
    }
    async updateMany(filter, update, options = {}) {
        return this.rawCollection.updateMany(tfbotRewriteFilter(filter, this.bucket), tfbotPrepareUpdate(update, this.bucket), options);
    }
    async deleteOne(filter, options = {}) {
        return this.rawCollection.deleteOne(tfbotRewriteFilter(filter, this.bucket), options);
    }
    async deleteMany(filter = {}, options = {}) {
        return this.rawCollection.deleteMany(tfbotRewriteFilter(filter, this.bucket), options);
    }
    async insertOne(document, options = {}) {
        return this.rawCollection.insertOne(tfbotPrepareDocument(document, this.bucket), options);
    }
    async insertMany(documents, options = {}) {
        return this.rawCollection.insertMany((Array.isArray(documents) ? documents : []).map(document => tfbotPrepareDocument(document, this.bucket)), options);
    }
    async bulkWrite(operations, options = {}) {
        const prepared = (Array.isArray(operations) ? operations : []).map(operation => {
            if (operation.insertOne) return { insertOne: { document: tfbotPrepareDocument(operation.insertOne.document, this.bucket) } };
            if (operation.updateOne) return { updateOne: { ...operation.updateOne, filter: tfbotRewriteFilter(operation.updateOne.filter, this.bucket), update: tfbotPrepareUpdate(operation.updateOne.update, this.bucket) } };
            if (operation.updateMany) return { updateMany: { ...operation.updateMany, filter: tfbotRewriteFilter(operation.updateMany.filter, this.bucket), update: tfbotPrepareUpdate(operation.updateMany.update, this.bucket) } };
            if (operation.deleteOne) return { deleteOne: { ...operation.deleteOne, filter: tfbotRewriteFilter(operation.deleteOne.filter, this.bucket) } };
            if (operation.deleteMany) return { deleteMany: { ...operation.deleteMany, filter: tfbotRewriteFilter(operation.deleteMany.filter, this.bucket) } };
            if (operation.replaceOne) return { replaceOne: { ...operation.replaceOne, filter: tfbotRewriteFilter(operation.replaceOne.filter, this.bucket), replacement: tfbotPrepareDocument(operation.replaceOne.replacement, this.bucket) } };
            return operation;
        });
        return this.rawCollection.bulkWrite(prepared, options);
    }
    async countDocuments(filter = {}, options = {}) {
        return this.rawCollection.countDocuments(tfbotRewriteFilter(filter, this.bucket), options);
    }
    async createIndex(keys, options = {}) {
        const fields = Object.entries(keys || {});
        const name = String(options.name || `${this.bucket}_${fields.map(([field, direction]) => `${field}_${direction}`).join('_')}`).slice(0, 110);
        if (options.expireAfterSeconds !== undefined && fields.length === 1 && fields[0][0] === 'expireAt') {
            return this.rawCollection.createIndex({ expireAt: 1 }, { ...options, name: 'tfbot_data_expire_at_ttl' });
        }
        if (options.expireAfterSeconds !== undefined && fields.length === 1 && fields[0][0] === 'leaseUntil') {
            return this.rawCollection.createIndex({ leaseUntil: 1 }, { ...options, name: 'tfbot_data_lease_until_ttl' });
        }
        if (options.expireAfterSeconds !== undefined && fields.length === 1 && fields[0][0] === 'createdAt') {
            return this.rawCollection.createIndex({ __tfbotExpiresAt: 1 }, { ...options, expireAfterSeconds: 0, name: 'tfbot_data_temporary_expiry_ttl' });
        }
        const compound = { __tfbotBucket: 1 };
        for (const [field, direction] of fields) compound[field] = direction;
        return this.rawCollection.createIndex(compound, { ...options, name: `tf_${name}`.slice(0, 120) });
    }
    async dropIndex(name) {
        const indexName = String(name || '');
        if (indexName === 'tfbot_data_expire_at_ttl' || indexName === 'tfbot_data_lease_until_ttl' || indexName === 'tfbot_data_temporary_expiry_ttl') return this.rawCollection.dropIndex(indexName);
        return this.rawCollection.dropIndex(`tf_${indexName}`.slice(0, 120));
    }
}

function createTfbotDatabase(targetDb) {
    const appCollection = targetDb.collection(TFBOT_APP_DATA_COLLECTION);
    const whatsappCollection = targetDb.collection(TFBOT_WHATSAPP_COLLECTION);
    const wrappers = new Map();
    return {
        databaseName: TFBOT_DATABASE_NAME,
        collection(name) {
            const bucket = String(name || '').trim();
            if (bucket === 'baileys_auth' || bucket === TFBOT_WHATSAPP_COLLECTION) return whatsappCollection;
            if (bucket === TFBOT_APP_DATA_COLLECTION) return appCollection;
            if (!TFBOT_LOGICAL_COLLECTIONS.has(bucket)) throw new Error(`tfbot_logical_collection_not_allowed:${bucket}`);
            if (!wrappers.has(bucket)) wrappers.set(bucket, new TfbotLogicalCollection(appCollection, bucket));
            return wrappers.get(bucket);
        }
    };
}

async function migrateTfbotStorage(targetDb) {
    const authTarget = targetDb.collection(TFBOT_WHATSAPP_COLLECTION);
    const appTarget = targetDb.collection(TFBOT_APP_DATA_COLLECTION);
    const sourceDbs = [targetDb];
    try {
        const legacyDb = mongoClient.db('dh7bot');
        if (legacyDb.databaseName !== targetDb.databaseName) sourceDbs.push(legacyDb);
    } catch (error) {
        console.warn('[tfbot-legacy-database-unavailable]', { error: error?.message || String(error) });
    }
    for (const sourceDb of sourceDbs) {
        let names = [];
        try {
            names = (await sourceDb.listCollections({}, { nameOnly: true }).toArray())
                .map(item => String(item.name || ''))
                .filter(name => name && !name.startsWith('system.') && name !== TFBOT_APP_DATA_COLLECTION && name !== TFBOT_WHATSAPP_COLLECTION && name !== 'server_runtime_logs');
        } catch (error) {
            console.warn('[tfbot-legacy-collection-list-failed]', { database: sourceDb.databaseName, error: error?.message || String(error) });
            continue;
        }
        for (const name of names) {
            const sourceCollection = sourceDb.collection(name);
            let copied = 0;
            try {
                const cursor = sourceCollection.find({}).batchSize(250);
                let batch = [];
                const flush = async () => {
                    if (!batch.length) return;
                    if (name === 'baileys_auth') {
                        for (const document of batch) {
                            const copy = cloneMongoValue(document);
                            await authTarget.updateOne(
                                { _id: copy._id },
                                { $setOnInsert: copy },
                                { upsert: true, writeConcern: { w: 'majority', wtimeout: 15000 } }
                            );
                        }
                    } else {
                        for (const document of batch) {
                            const copy = cloneMongoValue(document);
                            if (typeof copy._id === 'string') copy._id = tfbotNamespacedId(name, copy._id);
                            copy.__tfbotBucket = name;
                            if (name === 'baileys_outgoing_messages' && copy.createdAt) {
                                const createdAt = new Date(copy.createdAt).getTime();
                                if (Number.isFinite(createdAt)) copy.__tfbotExpiresAt = new Date(createdAt + BAILEYS_RETRY_MESSAGE_TTL_SECONDS * 1000);
                            }
                            await appTarget.updateOne(
                                { _id: copy._id },
                                { $setOnInsert: copy },
                                { upsert: true, writeConcern: { w: 'majority', wtimeout: 15000 } }
                            );
                        }
                    }
                    copied += batch.length;
                    batch = [];
                };
                while (await cursor.hasNext()) {
                    batch.push(await cursor.next());
                    if (batch.length >= 250) await flush();
                }
                await flush();
                await sourceCollection.drop();
                console.info('[tfbot-legacy-collection-migrated]', {
                    sourceDatabase: sourceDb.databaseName,
                    sourceCollection: name,
                    destinationCollection: name === 'baileys_auth' ? TFBOT_WHATSAPP_COLLECTION : TFBOT_APP_DATA_COLLECTION,
                    copiedDocuments: copied
                });
            } catch (error) {
                console.error('[tfbot-legacy-collection-migration-failed]', {
                    sourceDatabase: sourceDb.databaseName,
                    sourceCollection: name,
                    copiedDocuments: copied,
                    error: error?.message || String(error),
                    action: 'source_collection_preserved'
                });
                throw new Error(`tfbot_storage_migration_failed:${sourceDb.databaseName}:${name}`);
            }
        }
    }
}

async function connectMongo(options = {}) {
    if (!mongoUri) throw new Error('MONGO_URI is not configured');
    const coordinatorOnly = options.coordinatorOnly === true;
    const skipStorageInitialization = options.skipStorageInitialization === true;
    try {
        mongoClient = new MongoClient(mongoUri, { maxPoolSize: coordinatorOnly ? 8 : 30, minPoolSize: 0, serverSelectionTimeoutMS: 9000, connectTimeoutMS: 9000, retryWrites: true, appName: coordinatorOnly ? 'TFBotCoordinator' : 'TFBotWhatsAppBot' });
        await mongoClient.connect();
        const targetDb = mongoClient.db(TFBOT_DATABASE_NAME);
        for (const collectionName of [TFBOT_WHATSAPP_COLLECTION, TFBOT_APP_DATA_COLLECTION]) {
            try { await targetDb.createCollection(collectionName); } catch (error) {
                if (error?.codeName !== 'NamespaceExists' && error?.code !== 48) throw error;
            }
        }
        if (!skipStorageInitialization) await migrateTfbotStorage(targetDb);
        const listedPhysicalCollections = (await targetDb.listCollections({}, { nameOnly: true }).toArray()).map(item => String(item.name || '')).filter(name => !name.startsWith('system.') && name !== 'server_runtime_logs');
        const actualPhysicalCollections = listedPhysicalCollections.sort();
        const expectedPhysicalCollections = [TFBOT_APP_DATA_COLLECTION, TFBOT_WHATSAPP_COLLECTION].sort();
        const unexpectedPhysicalCollections = actualPhysicalCollections.filter(name => !expectedPhysicalCollections.includes(name));
        console.info('[tfbot-storage-layout-verified]', { database: TFBOT_DATABASE_NAME, expectedPhysicalCollections, actualPhysicalCollections, physicalCollectionCount: actualPhysicalCollections.length, unexpectedPhysicalCollections, role: coordinatorOnly ? 'coordinator' : 'serving' });
        if (unexpectedPhysicalCollections.length || actualPhysicalCollections.length !== 2) throw new Error(`tfbot_storage_layout_must_have_exactly_two_collections:${actualPhysicalCollections.join(',')}`);
        db = createTfbotDatabase(targetDb);
        if (skipStorageInitialization) {
            console.info('[tfbot-worker-storage-prepared]', { host: TFBOT_CLUSTER_INSTANCE_HOST, role: 'selected-worker-awaiting-selection-confirmation', migration: false, indexInitialization: false });
            return true;
        }
        await db.collection('cluster_router').createIndex({ updatedAt: -1 }, { name: 'cluster_router_updated_desc' });
        await db.collection('processed_messages').createIndex({ ts: 1 });
        await db.collection('processed_messages').createIndex({ expireAt: 1 }, { expireAfterSeconds: 0, name: 'processed_messages_expire_at_ttl' });
        await db.collection('baileys_outgoing_messages').createIndex({ createdAt: 1 }, { expireAfterSeconds: BAILEYS_RETRY_MESSAGE_TTL_SECONDS, name: 'baileys_retry_message_ttl' });
        await db.collection('lid_phone_mappings').createIndex({ expireAt: 1 }, { expireAfterSeconds: 0, name: 'lid_phone_mappings_expire_at_ttl' });
        await db.collection('lid_phone_mappings').createIndex({ sessionId: 1, phone: 1 }, { name: 'lid_phone_mappings_session_phone_lookup' });
        await db.collection('user_preferences').createIndex({ sessionId: 1, sender: 1 }, { name: 'user_preferences_session_sender' });
        await db.collection('user_preferences').createIndex({ expireAt: 1 }, { expireAfterSeconds: 0, name: 'user_preferences_expire_at_ttl' });
        await db.collection('group_del2').createIndex({ sessionId: 1, gjid: 1, targetJid: 1 });
        await db.collection('group_del3').createIndex({ sessionId: 1, gjid: 1, messageFormat: 1 }, { name: 'group_del3_format_lookup' });
        await db.collection('session_runtime_locks').createIndex({ leaseUntil: 1 }, { expireAfterSeconds: 0, name: 'session_runtime_locks_lease_ttl' });
        await db.collection('session_account_runtime_locks').createIndex({ leaseUntil: 1 }, { expireAfterSeconds: 0, name: 'session_account_runtime_locks_lease_ttl' });
        await db.collection('cluster_instances').createIndex({ status: 1, leaseUntil: 1, activeSessionCount: 1 }, { name: 'cluster_instances_candidate_lookup' });
        for (const [collectionName, indexName] of [
            ['baileys_outgoing_messages', 'baileys_retry_message_lookup'],
            ['baileys_outgoing_messages', 'baileys_retry_message_account_lookup'],
            ['session_owners', 'session_owners_account_number_lookup'],
            ['lid_phone_mappings', 'lid_phone_mappings_phone_lookup']
        ]) {
            try { await db.collection(collectionName).dropIndex(indexName); } catch (indexDropError) {
                if (!['IndexNotFound', 'NamespaceNotFound'].includes(String(indexDropError?.codeName || '')) && ![26, 27].includes(Number(indexDropError?.code))) console.warn('[obsolete-index-cleanup-skipped]', { collectionName, indexName, error: indexDropError?.message || String(indexDropError) });
            }
        }
        await db.collection('baileys_outgoing_messages').createIndex({ accountPhone: 1, messageId: 1, fromMe: 1, createdAt: -1 }, { name: 'baileys_retry_account_message_lookup' });
        await db.collection('baileys_outgoing_messages').createIndex({ accountLid: 1, messageId: 1, fromMe: 1, createdAt: -1 }, { name: 'baileys_retry_lid_message_lookup' });
        await db.collection('baileys_outgoing_messages').createIndex({ sessionId: 1, messageId: 1, fromMe: 1, createdAt: -1 }, { name: 'baileys_retry_session_message_lookup' });
        await db.collection('baileys_outgoing_messages').createIndex({ sessionId: 1, messageId: 1, retryLookupKeys: 1, fromMe: 1 }, { name: 'baileys_retry_session_pn_lid_alias_lookup' });
        await db.collection('session_owners').createIndex({ Number: 1 }, { name: 'session_owners_account_number_lookup' });
        await db.collection('session_owners').createIndex({ OwnerLid: 1 }, { name: 'session_owners_owner_lid_lookup' });
        try {
            const oldThreshold = Date.now() - PROCESSED_MESSAGE_RETENTION_MS;
            await db.collection('processed_messages').deleteMany({ ts: { $lt: oldThreshold }, expireAt: { $exists: false } });
            const preferenceThreshold = Date.now() - SESSION_PROFILE_RETENTION_MS;
            await db.collection('user_preferences').deleteMany({ updatedAt: { $type: 'number', $lt: preferenceThreshold }, expireAt: { $exists: false } });
            await db.collection('lid_phone_mappings').deleteMany({ updatedAt: { $lt: new Date(Date.now() - LID_PHONE_MAPPING_RETENTION_MS) } });
            await db.collection('lid_phone_mappings').deleteMany({ sessionId: { $exists: false } });
            await db.collection('baileys_outgoing_messages').deleteMany({ createdAt: { $lt: new Date(Date.now() - BAILEYS_RETRY_MESSAGE_TTL_SECONDS * 1000) } });
        } catch (retentionCleanupError) {
            console.warn('[mongo-retention-initial-cleanup-failed]', retentionCleanupError?.message || String(retentionCleanupError));
        }
    } catch (e) {
        console.error('[mongo] connection failed:', e?.message || e);
        throw e;
    }
}

function fixBuffers(obj) {
    if (obj === null || obj === undefined) return obj;
    if (obj._bsontype === 'Binary') {
        let binaryValue = null;
        try {
            if (typeof obj.value === 'function') binaryValue = obj.value(true);
        } catch (error) {}
        if (!binaryValue && obj.buffer) binaryValue = obj.buffer;
        if (binaryValue && (Buffer.isBuffer(binaryValue) || binaryValue instanceof Uint8Array)) {
            const length = Number.isInteger(obj.position) && obj.position >= 0 ? Math.min(obj.position, binaryValue.length) : binaryValue.length;
            return Buffer.from(binaryValue.subarray ? binaryValue.subarray(0, length) : binaryValue.slice(0, length));
        }
        if (Array.isArray(binaryValue) && binaryValue.every(value => Number.isInteger(value) && value >= 0 && value <= 255)) return Buffer.from(binaryValue);
        if (typeof binaryValue === 'string') {
            const encoded = binaryValue.trim().replace(/-/g, '+').replace(/_/g, '/');
            if (encoded && /^[A-Za-z0-9+/]*={0,2}$/.test(encoded) && encoded.length % 4 !== 1) {
                const normalized = encoded + '='.repeat((4 - encoded.length % 4) % 4);
                const decoded = Buffer.from(normalized, 'base64');
                if (decoded.length && decoded.toString('base64').replace(/=+$/, '') === normalized.replace(/=+$/, '')) return decoded;
            }
        }
    }
    if (Buffer.isBuffer(obj)) return Buffer.from(obj);
    if (obj instanceof Uint8Array) return Buffer.from(obj);
    if (obj instanceof ArrayBuffer) return Buffer.from(new Uint8Array(obj));
    if (ArrayBuffer.isView(obj) && !Buffer.isBuffer(obj)) return Buffer.from(obj.buffer, obj.byteOffset, obj.byteLength);
    if (Array.isArray(obj)) return obj.map(fixBuffers);
    if (typeof obj === 'object') {
        if (obj.type === 'Buffer' && Array.isArray(obj.data) && obj.data.every(value => Number.isInteger(Number(value)) && Number(value) >= 0 && Number(value) <= 255)) return Buffer.from(obj.data.map(Number));
        if (obj.type === 'Buffer' && obj.data && typeof obj.data === 'object' && !Array.isArray(obj.data)) {
            const dataKeys = Object.keys(obj.data).filter(key => key !== 'length');
            const dataLength = Number.isInteger(obj.data.length) ? obj.data.length : dataKeys.length;
            if (dataLength > 0 && dataKeys.length === dataLength && dataKeys.every((key, index) => key === String(index)) && dataKeys.every(key => Number.isInteger(Number(obj.data[key])) && Number(obj.data[key]) >= 0 && Number(obj.data[key]) <= 255)) return Buffer.from(dataKeys.map(key => Number(obj.data[key])));
        }
        if (obj.type === 'Buffer' && typeof obj.data === 'string') {
            const encoded = obj.data.trim().replace(/-/g, '+').replace(/_/g, '/');
            if (!encoded) return Buffer.alloc(0);
            if (!/^[A-Za-z0-9+/]*={0,2}$/.test(encoded) || encoded.length % 4 === 1) return obj;
            const normalized = encoded + '='.repeat((4 - encoded.length % 4) % 4);
            const decoded = Buffer.from(normalized, 'base64');
            if (!decoded.length || decoded.toString('base64').replace(/=+$/, '') !== normalized.replace(/=+$/, '')) return obj;
            return decoded;
        }
        if (obj.$binary && typeof obj.$binary.base64 === 'string') {
            const encoded = obj.$binary.base64.trim();
            if (/^[A-Za-z0-9+/]*={0,2}$/.test(encoded) && encoded.length % 4 !== 1) {
                const normalized = encoded + '='.repeat((4 - encoded.length % 4) % 4);
                const decoded = Buffer.from(normalized, 'base64');
                if (decoded.length && decoded.toString('base64').replace(/=+$/, '') === normalized.replace(/=+$/, '')) return decoded;
            }
        }
        const numericKeys = Object.keys(obj);
        if (numericKeys.length && numericKeys.every((key, index) => key === String(index)) && numericKeys.every(key => Number.isInteger(obj[key]) && obj[key] >= 0 && obj[key] <= 255)) {
            return Buffer.from(numericKeys.map(key => obj[key]));
        }
        const prototype = Object.getPrototypeOf(obj);
        if (prototype !== Object.prototype && prototype !== null) return obj;
        const output = Object.create(prototype);
        for (const key of Object.keys(obj)) output[key] = fixBuffers(obj[key]);
        return output;
    }
    return obj;
}

function restoreSignalSessionBuffer(value, depth = 0, seen = new WeakSet()) {
    if (value === null || value === undefined || depth > 9) return null;
    if (Buffer.isBuffer(value)) return value.length ? Buffer.from(value) : null;
    if (value instanceof Uint8Array) return value.byteLength ? Buffer.from(value) : null;
    if (value instanceof ArrayBuffer) return value.byteLength ? Buffer.from(new Uint8Array(value)) : null;
    if (ArrayBuffer.isView(value)) return value.byteLength ? Buffer.from(value.buffer, value.byteOffset, value.byteLength) : null;
    if (Array.isArray(value)) {
        if (value.length && value.every(item => Number.isInteger(item) && item >= 0 && item <= 255)) return Buffer.from(value);
        return null;
    }
    if (typeof value === 'string') {
        const encoded = value.trim().replace(/-/g, '+').replace(/_/g, '/');
        if (!encoded || !/^[A-Za-z0-9+/]*={0,2}$/.test(encoded) || encoded.length % 4 === 1) return null;
        const normalized = encoded + '='.repeat((4 - encoded.length % 4) % 4);
        const decoded = Buffer.from(normalized, 'base64');
        return decoded.length && decoded.toString('base64').replace(/=+$/, '') === normalized.replace(/=+$/, '') ? decoded : null;
    }
    if (typeof value !== 'object' || seen.has(value)) return null;
    seen.add(value);
    if (value._bsontype === 'Binary') {
        try {
            const raw = typeof value.value === 'function' ? value.value(true) : value.buffer;
            const restored = restoreSignalSessionBuffer(raw, depth + 1, seen);
            if (restored) {
                const position = Number(value.position);
                return Number.isInteger(position) && position > 0 && position < restored.length ? Buffer.from(restored.subarray(0, position)) : restored;
            }
        } catch (error) {}
    }
    for (const methodName of ['serialize', 'toBuffer', 'toUint8Array', 'toBytes', 'asBuffer']) {
        try {
            if (typeof value[methodName] !== 'function') continue;
            const serialized = value[methodName]();
            if (serialized === value) continue;
            const output = restoreSignalSessionBuffer(serialized, depth + 1, seen);
            if (output) return output;
        } catch (error) {}
    }
    if (typeof value.value === 'function') {
        try {
            const output = restoreSignalSessionBuffer(value.value(true), depth + 1, seen);
            if (output) return output;
        } catch (error) {}
    }
    if (typeof value.toJSON === 'function') {
        try {
            const jsonValue = value.toJSON();
            if (jsonValue !== value) {
                const output = restoreSignalSessionBuffer(jsonValue, depth + 1, seen);
                if (output) return output;
            }
        } catch (error) {}
    }
    if (value.buffer instanceof ArrayBuffer && Number.isInteger(value.byteOffset) && Number.isInteger(value.byteLength) && value.byteLength > 0) {
        return Buffer.from(value.buffer, value.byteOffset, value.byteLength);
    }
    const directKeys = Object.keys(value).filter(key => /^\d+$/.test(key)).sort((a, b) => Number(a) - Number(b));
    const extraKeys = Object.keys(value).filter(key => !/^\d+$/.test(key));
    if (directKeys.length && directKeys.every((key, index) => key === String(index)) && directKeys.every(key => Number.isInteger(Number(value[key])) && Number(value[key]) >= 0 && Number(value[key]) <= 255) && extraKeys.every(key => ['length', 'position', 'byteLength', 'byteOffset', 'type', 'sub_type', 'subType', '_bsontype'].includes(key))) {
        const bytes = Buffer.from(directKeys.map(key => Number(value[key])));
        const declaredLength = Number(value.position ?? value.byteLength ?? value.length);
        const restored = Number.isInteger(declaredLength) && declaredLength > 0 && declaredLength < bytes.length ? bytes.subarray(0, declaredLength) : bytes;
        if (restored.length) return Buffer.from(restored);
    }
    const fixed = fixBuffers(value);
    if (Buffer.isBuffer(fixed)) return fixed.length ? Buffer.from(fixed) : null;
    if (fixed instanceof Uint8Array) return fixed.byteLength ? Buffer.from(fixed) : null;
    if (fixed !== value && fixed && typeof fixed === 'object') {
        const output = restoreSignalSessionBuffer(fixed, depth + 1, seen);
        if (output) return output;
    }
    if (value.$binary && typeof value.$binary.base64 === 'string') {
        const output = restoreSignalSessionBuffer(value.$binary.base64, depth + 1, seen);
        if (output) return output;
    }
    const candidates = [value.buffer, value.bytes, value.byteArray, value.data, value.value, value.binary, value.base64, value.serialized, value.serializedBuffer, value.record, value.session, value.sessionRecord, value.content, value._value];
    for (const candidate of candidates) {
        if (candidate === value || candidate === undefined || candidate === null) continue;
        const output = restoreSignalSessionBuffer(candidate, depth + 1, seen);
        if (output) return output;
    }
    return null;
}

function isBinarySignalKeyCategory(type) {
    return ['sender-key', 'identity-key'].includes(String(type || ''));
}

function normalizeSignalSessionRecord(value) {
    let candidate = value;
    if (Buffer.isBuffer(candidate) || candidate instanceof Uint8Array || candidate instanceof ArrayBuffer || ArrayBuffer.isView(candidate)) {
        try {
            const bytes = Buffer.isBuffer(candidate) || ArrayBuffer.isView(candidate)
                ? Buffer.from(candidate.buffer || candidate, candidate.byteOffset || 0, candidate.byteLength || candidate.length)
                : Buffer.from(candidate);
            candidate = JSON.parse(bytes.toString('utf8'));
        } catch (error) {
            return null;
        }
    } else if (typeof candidate === 'string') {
        try {
            candidate = JSON.parse(candidate);
        } catch (error) {
            try {
                const bytes = restoreSignalSessionBuffer(candidate);
                if (!bytes) return null;
                candidate = JSON.parse(bytes.toString('utf8'));
            } catch (parseError) {
                return null;
            }
        }
    } else if (candidate && typeof candidate === 'object' && !Array.isArray(candidate) && (!candidate._sessions || typeof candidate._sessions !== 'object' || Array.isArray(candidate._sessions))) {
        try {
            const bytes = restoreSignalSessionBuffer(candidate);
            if (!bytes) return null;
            candidate = JSON.parse(bytes.toString('utf8'));
        } catch (error) {
            return null;
        }
    }
    if (!candidate || typeof candidate !== 'object' || Array.isArray(candidate)) return null;
    if (!candidate._sessions || typeof candidate._sessions !== 'object' || Array.isArray(candidate._sessions)) return null;
    if (candidate.version !== undefined && candidate.version !== null && !['string', 'number'].includes(typeof candidate.version)) return null;
    const normalized = fixBuffers(candidate);
    if (!normalized || typeof normalized !== 'object' || Array.isArray(normalized)) return null;
    if (!normalized._sessions || typeof normalized._sessions !== 'object' || Array.isArray(normalized._sessions)) return null;
    if (normalized.version !== undefined && normalized.version !== null && !['string', 'number'].includes(typeof normalized.version)) return null;
    return normalized;
}

function normalizeSignalKeyValue(type, value) {
    const category = String(type || '');
    if (category === 'session') return normalizeSignalSessionRecord(value);
    if (isBinarySignalKeyCategory(category)) return normalizeSignalBinaryValue(value);
    return fixBuffers(value);
}

function normalizeSignalBinaryValue(value) {
    const direct = restoreSignalSessionBuffer(value);
    if (direct && direct.length) return direct;
    if (!value || typeof value !== 'object' || typeof BufferJSON?.replacer !== 'function' || typeof BufferJSON?.reviver !== 'function') return null;
    try {
        const serialized = JSON.stringify(value, BufferJSON.replacer);
        if (!serialized) return null;
        const restored = JSON.parse(serialized, BufferJSON.reviver);
        const converted = restoreSignalSessionBuffer(restored);
        return converted && converted.length ? converted : null;
    } catch (error) {
        return null;
    }
}

function describeSignalSessionValue(value) {
    if (value === null || value === undefined) return { valueType: String(value) };
    if (Buffer.isBuffer(value)) return { valueType: 'Buffer', byteLength: value.length };
    if (value instanceof Uint8Array) return { valueType: value.constructor?.name || 'Uint8Array', byteLength: value.byteLength };
    if (ArrayBuffer.isView(value)) return { valueType: value.constructor?.name || 'ArrayBufferView', byteLength: value.byteLength };
    if (value instanceof ArrayBuffer) return { valueType: 'ArrayBuffer', byteLength: value.byteLength };
    if (Array.isArray(value)) return { valueType: 'Array', length: value.length };
    if (typeof value !== 'object') return { valueType: typeof value };
    let prototypeName = '';
    try { prototypeName = value.constructor?.name || Object.getPrototypeOf(value)?.constructor?.name || ''; } catch (error) {}
    return {
        valueType: 'object',
        constructor: prototypeName,
        bsonType: String(value._bsontype || ''),
        keys: Object.keys(value).slice(0, 16),
        hasSerialize: typeof value.serialize === 'function',
        hasToBuffer: typeof value.toBuffer === 'function',
        hasToJSON: typeof value.toJSON === 'function',
        byteLength: Number(value.byteLength || value.length || value.position || 0) || 0
    };
}

function cloneSignalKeyCacheValue(value, seen = new WeakMap()) {
    if (value === null || value === undefined || typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean' || typeof value === 'bigint') return value;
    if (Buffer.isBuffer(value)) return Buffer.from(value);
    if (value instanceof Uint8Array) return Buffer.from(value);
    if (value instanceof ArrayBuffer) return Buffer.from(new Uint8Array(value));
    if (ArrayBuffer.isView(value)) return Buffer.from(new Uint8Array(value.buffer, value.byteOffset, value.byteLength));
    if (value instanceof Date) return new Date(value.getTime());
    if (typeof value !== 'object') return null;
    if (seen.has(value)) return seen.get(value);
    if (Array.isArray(value)) {
        const output = [];
        seen.set(value, output);
        for (const item of value) {
            const cloned = cloneSignalKeyCacheValue(item, seen);
            if (cloned === null && item !== null && item !== undefined) return null;
            output.push(cloned);
        }
        return output;
    }
    const prototype = Object.getPrototypeOf(value);
    if (prototype !== Object.prototype && prototype !== null) return null;
    const output = Object.create(prototype);
    seen.set(value, output);
    for (const [key, item] of Object.entries(value)) {
        const cloned = cloneSignalKeyCacheValue(item, seen);
        if (cloned === null && item !== null && item !== undefined) return null;
        output[key] = cloned;
    }
    return output;
}

function createDurableSignalKeyStore(store, logger = null) {
    const cache = new Map();
    const cacheTtlMs = 5 * 60 * 1000;
    const cacheMaxEntries = 30000;
    let cacheQueue = Promise.resolve();
    let activeSignalTransactions = 0;
    let waitingSignalStoreWriters = 0;
    let signalStoreWriterActive = false;
    const signalStoreLockWaiters = [];
    const transactionContext = new AsyncLocalStorage();
    const waitForSignalStoreLockChange = () => new Promise(resolve => signalStoreLockWaiters.push(resolve));
    const wakeSignalStoreLockWaiters = () => {
        const waiters = signalStoreLockWaiters.splice(0);
        for (const resolve of waiters) resolve();
    };
    const acquireSignalTransactionReadLock = async () => {
        while (signalStoreWriterActive || waitingSignalStoreWriters > 0) await waitForSignalStoreLockChange();
        activeSignalTransactions++;
    };
    const releaseSignalTransactionReadLock = () => {
        activeSignalTransactions = Math.max(0, activeSignalTransactions - 1);
        if (activeSignalTransactions === 0) wakeSignalStoreLockWaiters();
    };
    const acquireSignalStoreWriteLock = async () => {
        waitingSignalStoreWriters++;
        try {
            while (signalStoreWriterActive || activeSignalTransactions > 0) await waitForSignalStoreLockChange();
        } finally {
            waitingSignalStoreWriters = Math.max(0, waitingSignalStoreWriters - 1);
        }
        signalStoreWriterActive = true;
    };
    const releaseSignalStoreWriteLock = () => {
        signalStoreWriterActive = false;
        wakeSignalStoreLockWaiters();
    };
    const runExclusive = operation => {
        if (transactionContext.getStore() === true) return Promise.resolve().then(operation);
        const execute = async () => {
            await acquireSignalStoreWriteLock();
            try {
                return await operation();
            } finally {
                releaseSignalStoreWriteLock();
            }
        };
        const result = cacheQueue.then(execute, execute);
        cacheQueue = result.catch(() => {});
        return result;
    };
    const cacheKey = (type, id) => `${String(type)}:${String(id)}`;
    const cacheSet = (type, id, value) => {
        const key = cacheKey(type, id);
        cache.delete(key);
        const snapshot = cloneSignalKeyCacheValue(value);
        if (snapshot === null && value !== null) return;
        cache.set(key, { value: snapshot, at: Date.now() });
        while (cache.size > cacheMaxEntries) cache.delete(cache.keys().next().value);
    };
    const cacheDelete = (type, id) => cache.delete(cacheKey(type, id));
    return {
        get: async (type, ids) => runExclusive(async () => {
            const result = {};
            const missing = [];
            const now = Date.now();
            for (const id of Array.isArray(ids) ? ids : []) {
                const key = cacheKey(type, id);
                const cached = cache.get(key);
                if (cached && now - Number(cached.at || 0) <= cacheTtlMs) {
                    const snapshot = cloneSignalKeyCacheValue(cached.value);
                    if (snapshot !== null || cached.value === null) {
                        result[id] = snapshot;
                        continue;
                    }
                    cache.delete(key);
                }
                if (cached) cache.delete(key);
                missing.push(id);
            }
            if (missing.length) {
                const fetched = await store.get(type, missing);
                for (const id of missing) {
                    const raw = fetched?.[id];
                    if (raw === null || raw === undefined) continue;
                    const value = normalizeSignalKeyValue(type, raw);
                    if (type === 'session' && !value) {
                        console.warn('[signal-auth-session-record-read-skipped-invalid]', { category: type, keyHash: shortLogHash(id), ...describeSignalSessionValue(raw), reason: 'session_record_requires_structured_sessions_object', action: 'preserve_stored_record_and_skip_invalid_value' });
                        continue;
                    }
                    if (isBinarySignalKeyCategory(type) && (!Buffer.isBuffer(value) || value.length === 0)) {
                        console.warn('[signal-auth-cache-read-skipped-invalid-binary-key]', { category: type, keyHash: shortLogHash(id), ...describeSignalSessionValue(raw), action: 'do_not_cache_or_return_non_binary_signal_record' });
                        continue;
                    }
                    const responseSnapshot = cloneSignalKeyCacheValue(value);
                    result[id] = responseSnapshot === null && value !== null ? value : responseSnapshot;
                    cacheSet(type, id, value);
                }
            }
            return result;
        }),
        set: async data => runExclusive(async () => {
            if (!data || typeof data !== 'object') return;
            const normalized = {};
            const updates = [];
            for (const [type, entries] of Object.entries(data)) {
                if (!entries || typeof entries !== 'object' || Array.isArray(entries)) continue;
                normalized[type] = {};
                for (const [id, raw] of Object.entries(entries)) {
                    if (raw === null || raw === undefined) {
                        normalized[type][id] = null;
                        updates.push({ type, id, value: null });
                        continue;
                    }
                    const value = normalizeSignalKeyValue(type, raw);
                    if (type === 'session' && !value) {
                        console.error('[signal-auth-session-record-write-rejected]', { category: type, keyHash: shortLogHash(id), ...describeSignalSessionValue(raw), reason: 'baileys_session_record_requires_structured_sessions_object', action: 'reject_without_polluting_signal_cache' });
                        throw new Error('signal_auth_session_record_write_invalid');
                    }
                    if (isBinarySignalKeyCategory(type) && (!Buffer.isBuffer(value) || value.length === 0)) {
                        console.error('[signal-auth-binary-key-normalization-failed]', { category: type, keyHash: shortLogHash(id), ...describeSignalSessionValue(raw), reason: 'baileys_signal_key_not_serialized_to_nonempty_bytes', action: 'reject_without_polluting_signal_cache' });
                        throw new Error(`signal_auth_${type.replace(/[^a-z0-9_-]/gi, '')}_write_not_binary`);
                    }
                    normalized[type][id] = value;
                    updates.push({ type, id, value });
                }
            }
            if (!Object.keys(normalized).length) return;
            await store.set(normalized);
            for (const update of updates) {
                if (update.value === null) cacheDelete(update.type, update.id);
                else cacheSet(update.type, update.id, update.value);
            }
            logger?.trace?.({ categoryCount: Object.keys(normalized).length, keyCount: updates.length }, 'durable signal key store committed');
        }),
        transaction: async (operation, transactionKey) => {
            if (typeof operation !== 'function') throw new Error('signal_key_store_transaction_callback_required');
            if (transactionContext.getStore() === true) {
                if (typeof store.transaction === 'function') return await store.transaction(operation, transactionKey);
                return await operation();
            }
            if (typeof store.transaction === 'function') {
                await acquireSignalTransactionReadLock();
                try {
                    return await transactionContext.run(true, () => store.transaction(operation, transactionKey));
                } finally {
                    releaseSignalTransactionReadLock();
                }
            }
            return await runExclusive(() => transactionContext.run(true, operation));
        },
        clear: async () => runExclusive(async () => {
            cache.clear();
            if (typeof store.clear === 'function') await store.clear();
        })
    };
}

async function assertSessionRuntimeOwnership(sessionId, options = {}) {
    const allowWorkerDrain = options?.allowWorkerDrain === true && workerDrainingSessionIds.has(sessionId);
    if (TFBOT_CLUSTER_COORDINATOR_ONLY || (TFBOT_CLUSTER_ENABLED && (!tfbotWorkerActive || tfbotWorkerStopping) && !allowWorkerDrain)) throw new Error('tfbot_worker_not_active');
    if (sessionFenceClosureInFlight.has(sessionId)) throw new Error('session_runtime_lock_fenced');
    const allowAccountBootstrap = options?.allowAccountBootstrap === true;
    const skipLiveAccountIdentityCheck = options?.skipLiveAccountIdentityCheck === true;
    const token = sessionRuntimeLockTokens.get(sessionId);
    if (!token || !db) throw new Error('session_runtime_lock_missing');
    const now = Date.now();
    const sessionLock = await db.collection('session_runtime_locks').findOne(
        { _id: sessionId, owner: processInstanceId, lockToken: token, leaseUntil: { $gt: new Date(now) } },
        { projection: { leaseUntil: 1 } }
    );
    if (!sessionLock) throw new Error('session_runtime_lock_lost');
    sessionRuntimeLockLeaseUntil.set(sessionId, new Date(sessionLock.leaseUntil).getTime());
    const accountEntries = sessionAccountRuntimeLockEntries.get(sessionId) || (() => {
        const accountKey = sessionAccountRuntimeLocks.get(sessionId);
        const accountToken = sessionAccountRuntimeLockTokens.get(sessionId);
        return accountKey && accountToken ? [{ key: accountKey, token: accountToken }] : [];
    })();
    let minimumAccountLease = Number.POSITIVE_INFINITY;
    const activeForOwnership = activeSessions.get(sessionId);
    if (!allowAccountBootstrap && !skipLiveAccountIdentityCheck && activeForOwnership?.sock) {
        const livePhone = getAuthenticatedPhoneNumber(activeForOwnership.sock.user, activeForOwnership.authState?.creds);
        const liveLid = getAuthenticatedLid(activeForOwnership.sock.user, activeForOwnership.authState?.creds);
        const credentialsRegistered = activeForOwnership?.authState?.creds?.registered === true;
        if (credentialsRegistered && (livePhone || liveLid) && !sessionHasAccountRuntimeLocks(sessionId, [livePhone, liveLid])) {
            const repaired = await ensureAccountRuntimeLockForIdentity(sessionId, activeForOwnership.sock.user, activeForOwnership.authState?.creds, { allowWorkerDrain });
            if (!repaired?.acquired || !sessionHasAccountRuntimeLocks(sessionId, [livePhone, liveLid])) throw new Error('account_runtime_lock_missing_or_incomplete');
            console.warn('[account-lock-auto-repaired-before-session-operation]', { sessionId, phoneIdentityKnown: !!livePhone, lidIdentityKnown: !!liveLid, lockCount: (sessionAccountRuntimeLockEntries.get(sessionId) || []).length });
        }
    }
    for (const entry of accountEntries) {
        if (!entry?.key || !entry?.token) throw new Error('account_runtime_lock_missing');
        const accountLock = await db.collection('session_account_runtime_locks').findOne(
            { _id: entry.key, owner: processInstanceId, sessionId, lockToken: entry.token, leaseUntil: { $gt: new Date(now) } },
            { projection: { leaseUntil: 1 } }
        );
        if (!accountLock) throw new Error('account_runtime_lock_lost');
        minimumAccountLease = Math.min(minimumAccountLease, new Date(accountLock.leaseUntil).getTime());
    }
    if (Number.isFinite(minimumAccountLease)) sessionAccountRuntimeLockLeaseUntil.set(sessionId, minimumAccountLease);
    return true;
}

async function ensureAccountRuntimeLockForIdentity(sessionId, user = null, creds = null, options = {}) {
    const ownershipOptions = { allowAccountBootstrap: true, allowWorkerDrain: options?.allowWorkerDrain === true };
    await assertSessionRuntimeOwnership(sessionId, ownershipOptions);
    const phone = getAuthenticatedPhoneNumber(user, creds);
    const lid = getAuthenticatedLid(user, creds);
    if (!phone && !lid) return { acquired: true, bootstrap: true, identityKnown: false };
    if (sessionHasAccountRuntimeLocks(sessionId, [phone, lid])) {
        await assertSessionRuntimeOwnership(sessionId, { skipLiveAccountIdentityCheck: true, allowWorkerDrain: options?.allowWorkerDrain === true });
        return { acquired: true, alreadyHeld: true, identityKnown: true };
    }
    const pending = accountRuntimeLockAcquisitionPromises.get(sessionId);
    if (pending) {
        await pending;
        return ensureAccountRuntimeLockForIdentity(sessionId, user, creds, options);
    }
    const acquisition = (async () => {
        const identity = phone || lid;
        const aliases = await expandAccountRuntimeLockAliases(sessionId, [phone, lid]);
        const result = await acquireAccountRuntimeLock(sessionId, identity, aliases);
        if (!result.acquired) {
            console.error('[auth-bootstrap-account-lock-conflict]', {
                sessionId,
                identityKnown: true,
                holderSessionId: result.holderSessionId || null,
                conflictingKeyHash: shortLogHash(result.conflictingKey || ''),
                action: 'block_auth_write_and_close_duplicate_socket'
            });
            setImmediate(() => {
                closeSessionSocketWithoutAuthFlush(sessionId, 'account_lock_conflict_during_auth_bootstrap', { status: 'duplicate_account', scheduleRetry: false }).catch(error => console.error('[auth-bootstrap-duplicate-close-failed]', { sessionId, error: error?.message || String(error) }));
            });
            throw new Error('account_runtime_lock_conflict_during_auth_bootstrap');
        }
        await assertSessionRuntimeOwnership(sessionId, { skipLiveAccountIdentityCheck: true, allowWorkerDrain: options?.allowWorkerDrain === true });
        console.info('[auth-bootstrap-account-lock-ready]', {
            sessionId,
            phoneIdentityKnown: !!phone,
            lidIdentityKnown: !!lid,
            accountLockCount: (sessionAccountRuntimeLockEntries.get(sessionId) || []).length
        });
        return result;
    })();
    accountRuntimeLockAcquisitionPromises.set(sessionId, acquisition);
    try {
        return await acquisition;
    } finally {
        if (accountRuntimeLockAcquisitionPromises.get(sessionId) === acquisition) accountRuntimeLockAcquisitionPromises.delete(sessionId);
    }
}

async function closeSessionSocketWithoutAuthFlush(sessionId, reason, options = {}) {
    if (!sessionId || sessionFenceClosureInFlight.has(sessionId)) return false;
    if (workerDrainingSessionIds.has(sessionId)) {
        console.info('[session-socket-close-owned-by-worker-drain]', { sessionId, reason: String(reason || 'worker_handoff') });
        return false;
    }
    sessionFenceClosureInFlight.add(sessionId);
    const active = activeSessions.get(sessionId) || null;
    const oldSocket = active?.sock || null;
    const oldFormat = active?.format || 'pair';
    try {
        if (active && activeSessions.get(sessionId) === active) {
            active.status = String(options.status || 'deconnecte');
            active.disconnectTime = Date.now();
            active.sock = null;
            active.runtimeLockLostReason = String(reason || 'runtime_lock_lost').slice(0, 120);
        }
        if (oldSocket) {
            try { oldSocket.ev.removeAllListeners(); } catch (e) {}
            const ws = oldSocket.ws;
            if (ws && ws.readyState !== 3) {
                await new Promise(resolve => {
                    let settled = false;
                    const finish = () => {
                        if (settled) return;
                        settled = true;
                        clearTimeout(timer);
                        try { ws.removeListener('close', finish); } catch (e) {}
                        resolve();
                    };
                    const timer = setTimeout(finish, 2500);
                    if (typeof timer.unref === 'function') timer.unref();
                    try { ws.once('close', finish); } catch (e) {}
                    try { ws.close(); } catch (e) { finish(); }
                });
            }
        }
        console.error('[session-socket-fenced]', { sessionId, reason, authStatePreserved: true, staleAuthWritesBlocked: true, retryScheduled: !serverShuttingDown });
        await releaseSessionRuntimeLock(sessionId);
    } finally {
        sessionFenceClosureInFlight.delete(sessionId);
    }
    if (!serverShuttingDown && !tfbotWorkerStopping && (!TFBOT_CLUSTER_ENABLED || tfbotWorkerActive) && activeSessions.has(sessionId) && options.scheduleRetry !== false) scheduleSessionLockRetry(sessionId, false, oldFormat);
    return true;
}

async function acquireSessionRuntimeLock(sessionId) {
    if (!db) throw new Error('mongo_not_connected');
    const now = new Date();
    const currentToken = sessionRuntimeLockTokens.get(sessionId);
    if (!currentToken) {
        const activeWithoutToken = activeSessions.get(sessionId);
        if (activeWithoutToken?.sock) {
            await closeSessionSocketWithoutAuthFlush(sessionId, 'active_socket_missing_session_fencing_token');
            return false;
        }
    }
    if (currentToken) {
        const existing = await db.collection('session_runtime_locks').findOne(
            { _id: sessionId, owner: processInstanceId, lockToken: currentToken, leaseUntil: { $gt: now } },
            { projection: { leaseUntil: 1 } }
        ).catch(() => null);
        if (existing) {
            const leaseUntil = new Date(Date.now() + SESSION_RUNTIME_LOCK_LEASE_MS);
            const renewed = await db.collection('session_runtime_locks').updateOne(
                { _id: sessionId, owner: processInstanceId, lockToken: currentToken },
                { $set: { leaseUntil, updatedAt: new Date() } }
            );
            if (renewed.matchedCount === 1) {
                sessionRuntimeLockLeaseUntil.set(sessionId, leaseUntil.getTime());
                return true;
            }
        }
        const oldTimer = sessionRuntimeLockTimers.get(sessionId);
        if (oldTimer) clearInterval(oldTimer);
        sessionRuntimeLockTimers.delete(sessionId);
        const currentSession = activeSessions.get(sessionId);
        if (currentSession?.sock) {
            await closeSessionSocketWithoutAuthFlush(sessionId, 'session_lock_token_unverifiable_during_reacquire');
            return false;
        }
        sessionRuntimeLockTokens.delete(sessionId);
        sessionRuntimeLockLeaseUntil.delete(sessionId);
    }
    if (sessionFenceClosureInFlight.has(sessionId)) return false;
    let previousOwnerInstanceId = previousDeploymentSessionTakeoverOwners.get(sessionId) || '';
    if (TFBOT_CLUSTER_ENABLED && !previousOwnerInstanceId) {
        const ownerRecord = await db.collection('session_owners').findOne({ sessionId }, { projection: { ownerInstanceId: 1, ownerInstanceUrl: 1, ownerDeploymentId: 1 } }).catch(() => null);
        if (isPreviousDeploymentOwnerOnCurrentHost(ownerRecord)) {
            previousOwnerInstanceId = String(ownerRecord.ownerInstanceId || '');
            previousDeploymentSessionTakeoverOwners.set(sessionId, previousOwnerInstanceId);
        }
    }
    const lockToken = crypto.randomUUID();
    const leaseUntil = new Date(Date.now() + SESSION_RUNTIME_LOCK_LEASE_MS);
    let lockAcquired = false;
    if (previousOwnerInstanceId) {
        const previousLock = await db.collection('session_runtime_locks').findOne({ _id: sessionId }, { projection: { owner: 1, lockToken: 1, leaseUntil: 1 } }).catch(() => null);
        const previousOwnerPrefix = `${previousOwnerInstanceId}-`;
        if (previousLock?.lockToken && String(previousLock.owner || '').startsWith(previousOwnerPrefix)) {
            const takeover = await db.collection('session_runtime_locks').updateOne(
                { _id: sessionId, owner: previousLock.owner, lockToken: previousLock.lockToken },
                { $set: { owner: processInstanceId, lockToken, leaseUntil, updatedAt: new Date(), acquiredAt: new Date(), handoffFrom: previousLock.owner } }
            ).catch(error => { throw error; });
            lockAcquired = takeover.matchedCount === 1;
            if (lockAcquired) console.warn('[session-runtime-lock-previous-deployment-handoff]', { sessionId, previousOwnerInstanceId, action: 'fence_previous_render_process_and_restore_session_immediately' });
        }
    }
    if (!lockAcquired) {
        try {
            const result = await db.collection('session_runtime_locks').updateOne(
                { _id: sessionId, $or: [{ leaseUntil: { $lte: now } }, { leaseUntil: { $exists: false } }] },
                { $set: { owner: processInstanceId, lockToken, leaseUntil, updatedAt: now, acquiredAt: now } },
                { upsert: true }
            );
            lockAcquired = result.matchedCount === 1 || result.upsertedCount === 1;
        } catch (error) {
            if (error?.code !== 11000) throw error;
            return false;
        }
    }
    if (!lockAcquired) return false;
    sessionRuntimeLockTokens.set(sessionId, lockToken);
    sessionRuntimeLockLeaseUntil.set(sessionId, leaseUntil.getTime());
    if (!sessionRuntimeLockTimers.has(sessionId)) {
        let failures = 0;
        let heartbeatRunning = false;
        let timer;
        timer = setInterval(async () => {
            if (heartbeatRunning || serverShuttingDown || tfbotWorkerStopping || workerDrainingSessionIds.has(sessionId)) return;
            heartbeatRunning = true;
            try {
                const nextLease = new Date(Date.now() + SESSION_RUNTIME_LOCK_LEASE_MS);
                const heartbeat = await db.collection('session_runtime_locks').updateOne(
                    { _id: sessionId, owner: processInstanceId, lockToken },
                    { $set: { leaseUntil: nextLease, updatedAt: new Date() } }
                );
                if (heartbeat.matchedCount === 1) {
                    failures = 0;
                    sessionRuntimeLockLeaseUntil.set(sessionId, nextLease.getTime());
                    return;
                }
                await closeSessionSocketWithoutAuthFlush(sessionId, 'session_lock_owned_by_another_runtime');
            } catch (error) {
                failures++;
                console.warn('[session-runtime-lock-heartbeat-failed]', { sessionId, failures, error: error?.message || String(error) });
                if (failures >= 3) await closeSessionSocketWithoutAuthFlush(sessionId, 'session_lock_heartbeat_unverified');
            } finally {
                heartbeatRunning = false;
            }
        }, SESSION_RUNTIME_LOCK_RENEW_MS);
        if (typeof timer.unref === 'function') timer.unref();
        sessionRuntimeLockTimers.set(sessionId, timer);
    }
    console.info('[session-runtime-lock-acquired]', { sessionId, processInstanceId, leaseMs: SESSION_RUNTIME_LOCK_LEASE_MS, fencingToken: shortLogHash(lockToken) });
    return true;
}

function normalizeAccountRuntimeLockKey(value) {
    const raw = String(value || '').trim();
    if (!raw) return '';
    const number = normalizePhoneNumber(raw);
    if (/^\d{6,20}$/.test(number) && (!raw.includes('@') || /@s\.whatsapp\.net$|@c\.us$/i.test(raw))) return number;
    const lid = normalizeLidCacheKey(raw);
    if (/@lid$/i.test(lid)) return `lid:${lid}`;
    return '';
}

function getAccountRuntimeLockKeys(...identities) {
    return [...new Set(identities.flat().map(normalizeAccountRuntimeLockKey).filter(Boolean))].sort();
}

function sessionHasAccountRuntimeLocks(sessionId, identities) {
    const required = getAccountRuntimeLockKeys(identities || []);
    if (!required.length) return true;
    const heldEntries = sessionAccountRuntimeLockEntries.get(sessionId) || (() => {
        const key = sessionAccountRuntimeLocks.get(sessionId);
        const token = sessionAccountRuntimeLockTokens.get(sessionId);
        return key && token ? [{ key, token }] : [];
    })();
    const held = new Set(heldEntries.map(entry => entry.key));
    return required.every(key => held.has(key));
}

async function releaseAccountRuntimeLock(sessionId) {
    const timer = accountRuntimeLockTimers.get(sessionId);
    if (timer) clearInterval(timer);
    accountRuntimeLockTimers.delete(sessionId);
    const entries = sessionAccountRuntimeLockEntries.get(sessionId) || (() => {
        const key = sessionAccountRuntimeLocks.get(sessionId);
        const token = sessionAccountRuntimeLockTokens.get(sessionId);
        return key && token ? [{ key, token }] : [];
    })();
    sessionAccountRuntimeLockEntries.delete(sessionId);
    sessionAccountRuntimeLocks.delete(sessionId);
    sessionAccountRuntimeLockTokens.delete(sessionId);
    sessionAccountRuntimeLockLeaseUntil.delete(sessionId);
    if (!db || !entries.length) return;
    for (const entry of entries) {
        if (!entry?.key || !entry?.token) {
            console.warn('[session-account-runtime-lock-release-skipped]', { sessionId, accountKey: entry?.key || null, reason: 'missing_fencing_token_leave_record_to_expire' });
            continue;
        }
        try {
            await db.collection('session_account_runtime_locks').deleteOne({
                _id: entry.key,
                owner: processInstanceId,
                sessionId,
                lockToken: entry.token
            });
            console.info('[session-account-runtime-lock-released]', { sessionId, accountKey: entry.key });
        } catch (error) {
            console.warn('[session-account-runtime-lock-release-failed]', { sessionId, accountKey: entry.key, error: error?.message || String(error) });
        }
    }
}

async function expandAccountRuntimeLockAliases(sessionId, identityValues = []) {
    const values = [...new Set((Array.isArray(identityValues) ? identityValues.flat(Infinity) : [identityValues]).map(value => String(value || '').trim()).filter(Boolean))];
    const phones = [...new Set(values.map(value => {
        const raw = String(value || '').trim();
        if (/@/i.test(raw)) return normalizePhoneCacheJid(raw);
        const number = normalizePhoneNumber(raw);
        return /^\d{6,20}$/.test(number) ? `${number}@s.whatsapp.net` : '';
    }).filter(Boolean))];
    const lids = [...new Set(values.map(normalizeLidCacheKey).filter(value => /@lid$/i.test(value)))];
    if (!db || (!phones.length && !lids.length)) return values;
    const clauses = [];
    for (const phoneJid of phones) {
        const phone = normalizedJidNumber(phoneJid);
        if (!phone) continue;
        clauses.push({ Number: phone }, { number: phone }, { AccountJid: phoneJid }, { accountJid: phoneJid });
    }
    for (const lid of lids) clauses.push({ OwnerLid: lid }, { ownerLid: lid }, { AccountJid: lid }, { accountJid: lid });
    if (!clauses.length) return values;
    try {
        const records = await db.collection('session_owners').find(
            { sessionId: { $ne: sessionId }, $or: clauses },
            { projection: { Number: 1, number: 1, OwnerLid: 1, ownerLid: 1, AccountJid: 1, accountJid: 1 } }
        ).limit(100).toArray();
        for (const record of records) {
            for (const candidate of [record?.Number, record?.number, record?.OwnerLid, record?.ownerLid, record?.AccountJid, record?.accountJid]) {
                const candidateValue = String(candidate || '').trim();
                if (candidateValue) values.push(candidateValue);
            }
        }
        const mappingClauses = [];
        if (phones.length) mappingClauses.push({ phone: { $in: phones } });
        for (const lid of lids) {
            const escapedLid = lid.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
            mappingClauses.push({ _id: { $regex: `:${escapedLid}$` } });
        }
        let mappingCount = 0;
        if (mappingClauses.length) {
            const mappings = await db.collection('lid_phone_mappings').find(
                { expireAt: { $gt: new Date() }, $or: mappingClauses },
                { projection: { _id: 1, phone: 1, sessionId: 1 } }
            ).limit(200).toArray();
            mappingCount = mappings.length;
            for (const mapping of mappings) {
                const phone = normalizePhoneCacheJid(mapping?.phone || '');
                const mappingId = String(mapping?._id || '');
                const separatorIndex = mappingId.lastIndexOf(':');
                const lid = separatorIndex >= 0 ? normalizeLidCacheKey(mappingId.slice(separatorIndex + 1)) : '';
                if (phone) values.push(phone);
                if (/@lid$/i.test(lid)) values.push(lid);
            }
        }
        console.info('[account-runtime-lock-aliases-expanded]', { sessionId, inputIdentityCount: phones.length + lids.length, matchedSessionRecords: records.length, matchedActiveLidMappings: mappingCount, lockIdentityCount: getAccountRuntimeLockKeys(values).length, sessionScopedMappingsUsedOnlyForAccountExclusivity: true });
    } catch (error) {
        console.warn('[account-runtime-lock-alias-expansion-failed]', { sessionId, error: error?.message || String(error), action: 'use_only_live_authenticated_identity_aliases' });
    }
    return [...new Set(values)];
}

async function acquireAccountRuntimeLock(sessionId, identityValue, identityAliases = []) {
    const requestedKeys = getAccountRuntimeLockKeys(identityValue, identityAliases);
    if (!requestedKeys.length) return { acquired: true, accountPhone: null, accountKeys: [], reason: 'account_identity_unavailable' };
    if (!db) throw new Error('mongo_not_connected');

    const previousEntries = sessionAccountRuntimeLockEntries.get(sessionId) || (() => {
        const key = sessionAccountRuntimeLocks.get(sessionId);
        const token = sessionAccountRuntimeLockTokens.get(sessionId);
        return key && token ? [{ key, token }] : [];
    })();
    const previousByKey = new Map(previousEntries.map(entry => [entry.key, entry]));
    const acquiredEntries = [];
    const newlyAcquired = [];
    const now = new Date();
    const leaseUntil = new Date(Date.now() + SESSION_RUNTIME_LOCK_LEASE_MS);

    const releaseNewlyAcquired = async () => {
        for (const entry of newlyAcquired) {
            await db.collection('session_account_runtime_locks').deleteOne({
                _id: entry.key,
                owner: processInstanceId,
                sessionId,
                lockToken: entry.token
            }).catch(() => {});
        }
    };

    for (const accountKey of requestedKeys) {
        const previous = previousByKey.get(accountKey);
        if (previous?.token) {
            const existing = await db.collection('session_account_runtime_locks').findOne(
                { _id: accountKey, owner: processInstanceId, sessionId, lockToken: previous.token, leaseUntil: { $gt: now } },
                { projection: { leaseUntil: 1 } }
            ).catch(() => null);
            if (existing) {
                const renewed = await db.collection('session_account_runtime_locks').updateOne(
                    { _id: accountKey, owner: processInstanceId, sessionId, lockToken: previous.token, leaseUntil: { $gt: now } },
                    { $set: { leaseUntil, updatedAt: new Date() } }
                ).catch(() => null);
                if (renewed?.matchedCount === 1) {
                    acquiredEntries.push({ key: accountKey, token: previous.token, leaseUntil: leaseUntil.getTime() });
                    continue;
                }
            }
        }

        const lockToken = crypto.randomUUID();
        let accountLockAcquired = false;
        try {
            const result = await db.collection('session_account_runtime_locks').updateOne(
                { _id: accountKey, $or: [{ leaseUntil: { $lte: now } }, { leaseUntil: { $exists: false } }] },
                { $set: { owner: processInstanceId, sessionId, lockToken, leaseUntil, updatedAt: now, acquiredAt: now } },
                { upsert: true }
            );
            accountLockAcquired = result.matchedCount === 1 || result.upsertedCount === 1;
        } catch (error) {
            if (error?.code !== 11000) {
                await releaseNewlyAcquired();
                throw error;
            }
        }
        if (!accountLockAcquired) {
            const holder = await db.collection('session_account_runtime_locks').findOne({ _id: accountKey }, { projection: { owner: 1, sessionId: 1, lockToken: 1, leaseUntil: 1 } }).catch(() => null);
            const previousOwnerInstanceId = previousDeploymentSessionTakeoverOwners.get(sessionId) || '';
            const previousOwnerPrefix = previousOwnerInstanceId ? `${previousOwnerInstanceId}-` : '';
            if (previousOwnerPrefix && holder?.sessionId === sessionId && holder?.lockToken && String(holder.owner || '').startsWith(previousOwnerPrefix)) {
                const takeover = await db.collection('session_account_runtime_locks').updateOne(
                    { _id: accountKey, owner: holder.owner, sessionId, lockToken: holder.lockToken },
                    { $set: { owner: processInstanceId, sessionId, lockToken, leaseUntil, updatedAt: new Date(), acquiredAt: new Date(), handoffFrom: holder.owner } }
                );
                accountLockAcquired = takeover.matchedCount === 1;
                if (accountLockAcquired) console.warn('[session-account-runtime-lock-previous-deployment-handoff]', { sessionId, accountKeyHash: shortLogHash(accountKey), previousOwnerInstanceId, action: 'transfer_only_the_same_session_account_lock' });
            }
            if (!accountLockAcquired) {
                await releaseNewlyAcquired();
                return { acquired: false, accountPhone: requestedKeys[0], accountKeys: requestedKeys, conflictingKey: accountKey, holderSessionId: holder?.sessionId || null, holderOwner: holder?.owner || null, leaseUntil: holder?.leaseUntil || null };
            }
        }
        const createdEntry = { key: accountKey, token: lockToken, leaseUntil: leaseUntil.getTime() };
        acquiredEntries.push(createdEntry);
        newlyAcquired.push(createdEntry);
    }

    const nextKeySet = new Set(requestedKeys);
    for (const oldEntry of previousEntries) {
        if (nextKeySet.has(oldEntry.key)) continue;
        if (!oldEntry?.key || !oldEntry?.token) continue;
        await db.collection('session_account_runtime_locks').deleteOne({
            _id: oldEntry.key,
            owner: processInstanceId,
            sessionId,
            lockToken: oldEntry.token
        }).catch(() => {});
    }

    const oldTimer = accountRuntimeLockTimers.get(sessionId);
    if (oldTimer) clearInterval(oldTimer);
    accountRuntimeLockTimers.delete(sessionId);
    sessionAccountRuntimeLockEntries.set(sessionId, acquiredEntries);
    sessionAccountRuntimeLocks.set(sessionId, requestedKeys[0]);
    sessionAccountRuntimeLockTokens.set(sessionId, acquiredEntries[0]?.token || '');
    sessionAccountRuntimeLockLeaseUntil.set(sessionId, leaseUntil.getTime());

    let failures = 0;
    let heartbeatRunning = false;
    const heartbeatEntries = acquiredEntries.map(entry => ({ key: entry.key, token: entry.token }));
    const timer = setInterval(async () => {
        if (heartbeatRunning || serverShuttingDown || tfbotWorkerStopping || workerDrainingSessionIds.has(sessionId) || sessionFenceClosureInFlight.has(sessionId)) return;
        heartbeatRunning = true;
        try {
            const nextLease = new Date(Date.now() + SESSION_RUNTIME_LOCK_LEASE_MS);
            for (const entry of heartbeatEntries) {
                const heartbeat = await db.collection('session_account_runtime_locks').updateOne(
                    { _id: entry.key, owner: processInstanceId, sessionId, lockToken: entry.token, leaseUntil: { $gt: new Date() } },
                    { $set: { leaseUntil: nextLease, updatedAt: new Date() } }
                );
                if (heartbeat.matchedCount !== 1) {
                    await closeSessionSocketWithoutAuthFlush(sessionId, 'account_lock_owned_by_another_runtime');
                    return;
                }
            }
            failures = 0;
            sessionAccountRuntimeLockLeaseUntil.set(sessionId, nextLease.getTime());
        } catch (error) {
            failures++;
            console.warn('[session-account-runtime-lock-heartbeat-failed]', { sessionId, accountKeyCount: heartbeatEntries.length, failures, error: error?.message || String(error) });
            if (failures >= 3) await closeSessionSocketWithoutAuthFlush(sessionId, 'account_lock_heartbeat_unverified');
        } finally {
            heartbeatRunning = false;
        }
    }, SESSION_RUNTIME_LOCK_RENEW_MS);
    if (typeof timer.unref === 'function') timer.unref();
    accountRuntimeLockTimers.set(sessionId, timer);
    console.info('[session-account-runtime-lock-acquired]', { sessionId, accountKeyCount: requestedKeys.length, accountKeyHashes: requestedKeys.map(shortLogHash), processInstanceId, leaseMs: SESSION_RUNTIME_LOCK_LEASE_MS, fencingTokens: acquiredEntries.map(entry => shortLogHash(entry.token)) });
    return { acquired: true, accountPhone: requestedKeys[0], accountKeys: requestedKeys, reason: 'account_locks_acquired' };
}

async function releaseSessionRuntimeLock(sessionId) {
    const timer = sessionRuntimeLockTimers.get(sessionId);
    if (timer) clearInterval(timer);
    sessionRuntimeLockTimers.delete(sessionId);
    const retryTimer = sessionLockRetryTimers.get(sessionId);
    if (retryTimer) clearTimeout(retryTimer);
    sessionLockRetryTimers.delete(sessionId);
    sessionLockRetryDueAt.delete(sessionId);
    await releaseAccountRuntimeLock(sessionId);
    const lockToken = sessionRuntimeLockTokens.get(sessionId);
    sessionRuntimeLockTokens.delete(sessionId);
    sessionRuntimeLockLeaseUntil.delete(sessionId);
    if (!db) return;
    if (!lockToken) {
        console.warn('[session-runtime-lock-release-skipped]', { sessionId, reason: 'missing_fencing_token_leave_record_to_expire' });
        return;
    }
    try {
        const filter = { _id: sessionId, owner: processInstanceId, lockToken };
        await db.collection('session_runtime_locks').deleteOne(filter);
    } catch (error) {
        console.warn('[session-runtime-lock-release-failed]', { sessionId, error: error?.message || String(error) });
    }
}

async function clearSessionRestoreFailure(sessionId, runtime = activeSessions.get(sessionId)) {
    if (runtime) runtime.lastRestoreError = null;
    if (!db || !sessionId) return;
    await db.collection('session_owners').updateOne({ sessionId }, { $unset: { lastRestoreError: 1, lastRestoreErrorHash: 1, nextRestoreRetryAt: 1 } }).catch(() => {});
}

function scheduleSessionLockRetry(sessionId, autoExpire, format) {
    if (serverShuttingDown || tfbotWorkerStopping || (TFBOT_CLUSTER_ENABLED && !tfbotWorkerActive) || sessionLockRetryTimers.has(sessionId)) return 0;
    const retryAttempt = Math.min(10, Number(sessionLockRetryAttempts.get(sessionId) || 0) + 1);
    sessionLockRetryAttempts.set(sessionId, retryAttempt);
    const delay = Math.min(120000, 1000 * (2 ** (retryAttempt - 1))) + Math.floor(Math.random() * 1000);
    const timer = setTimeout(async () => {
        sessionLockRetryTimers.delete(sessionId);
        sessionLockRetryDueAt.delete(sessionId);
        try {
            await startAdamBot(sessionId, autoExpire, format, true);
        } catch (error) {
            console.warn('[session-restore-retry-failed]', { sessionId, attempt: retryAttempt, retryInMs: delay, error: error?.message || String(error) });
            scheduleSessionLockRetry(sessionId, autoExpire, format);
        }
    }, delay);
    if (typeof timer.unref === 'function') timer.unref();
    sessionLockRetryTimers.set(sessionId, timer);
    sessionLockRetryDueAt.set(sessionId, Date.now() + delay);
    return delay;
}

async function useMongoAuthState(sessionId, expectExisting = false) {
    await flushAuthWritesForSession(sessionId);
    const collection = db.collection('baileys_auth');
    const sessionKey = `auth-${sessionId}`;
    const credsId = `${sessionKey}-creds`;
    const credsDoc = await collection.findOne({ _id: credsId });
    if (expectExisting && !credsDoc) throw new Error('SessionNotExists');
    const creds = credsDoc ? fixBuffers(credsDoc.creds) : initAuthCreds();
    const migratedLegacyCategories = new Set();
    let authSocket = null;
    const authTransactionContext = new AsyncLocalStorage();
    const authTransactionQueues = new Map();
    const setAuthSocket = socket => { authSocket = socket || null; };
    const queueAuthWrite = operation => {
        if (authTransactionContext.getStore() === sessionId) return Promise.resolve().then(operation);
        const previous = authWriteQueues.get(sessionId) || Promise.resolve();
        authWriteActivityAt.set(sessionId, Date.now());
        const run = previous.catch(() => {}).then(async () => {
            if (pairingSessionsBeingExpired.has(sessionId)) throw new Error('pairing_challenge_expired');
            const allowWorkerDrain = workerDrainingSessionIds.has(sessionId);
            await assertSessionRuntimeOwnership(sessionId, { allowAccountBootstrap: true, allowWorkerDrain });
            const liveSocket = authSocket || activeSessions.get(sessionId)?.sock || null;
            await ensureAccountRuntimeLockForIdentity(sessionId, liveSocket?.user || null, creds, { allowWorkerDrain });
            const phone = getAuthenticatedPhoneNumber(liveSocket?.user || null, creds);
            const lid = getAuthenticatedLid(liveSocket?.user || null, creds);
            await assertSessionRuntimeOwnership(sessionId, { allowAccountBootstrap: !phone && !lid, skipLiveAccountIdentityCheck: true, allowWorkerDrain });
            return operation();
        });
        authWriteQueues.set(sessionId, run);
        run.then(() => {
            authWriteActivityAt.set(sessionId, Date.now());
            authWriteFailures.delete(sessionId);
        }, error => {
            authWriteActivityAt.set(sessionId, Date.now());
            authWriteFailures.set(sessionId, { at: Date.now(), message: String(error?.message || error).slice(0, 240) });
        });
        return run;
    };
    const queueAuthTransaction = (transactionKey, operation) => {
        if (authTransactionContext.getStore() === sessionId) return Promise.resolve().then(operation);
        const normalizedTransactionKey = String(transactionKey || 'session-wide').trim().slice(0, 240) || 'session-wide';
        const enqueuedAt = Date.now();
        const previous = authTransactionQueues.get(normalizedTransactionKey) || Promise.resolve();
        const run = previous.catch(() => {}).then(async () => {
            const queueWaitMs = Date.now() - enqueuedAt;
            if (pairingSessionsBeingExpired.has(sessionId)) throw new Error('pairing_challenge_expired');
            const allowWorkerDrain = workerDrainingSessionIds.has(sessionId);
            const liveSocket = authSocket || activeSessions.get(sessionId)?.sock || null;
            const phone = getAuthenticatedPhoneNumber(liveSocket?.user || null, creds);
            const lid = getAuthenticatedLid(liveSocket?.user || null, creds);
            const ownershipStartedAt = Date.now();
            if ((phone || lid) && !sessionHasAccountRuntimeLocks(sessionId, [phone, lid])) {
                await ensureAccountRuntimeLockForIdentity(sessionId, liveSocket?.user || null, creds, { allowWorkerDrain });
            } else {
                await assertSessionRuntimeOwnership(sessionId, { allowAccountBootstrap: !phone && !lid, skipLiveAccountIdentityCheck: true, allowWorkerDrain });
            }
            const ownershipCheckMs = Date.now() - ownershipStartedAt;
            const transactionStartedAt = Date.now();
            try {
                return await authTransactionContext.run(sessionId, async () => operation());
            } finally {
                const transactionDurationMs = Date.now() - transactionStartedAt;
                if (queueWaitMs >= 250 || ownershipCheckMs >= 350 || transactionDurationMs >= 500) {
                    console.warn('[signal-transaction-latency]', {
                        sessionId,
                        transactionKeyHash: shortLogHash(normalizedTransactionKey),
                        queueWaitMs,
                        ownershipCheckMs,
                        transactionDurationMs,
                        transactionMode: 'per-signal-peer-or-group'
                    });
                }
            }
        });
        authTransactionQueues.set(normalizedTransactionKey, run);
        run.finally(() => {
            if (authTransactionQueues.get(normalizedTransactionKey) === run) authTransactionQueues.delete(normalizedTransactionKey);
        }).catch(() => {});
        return run;
    };
    const flushAuthWrites = () => flushAuthWritesForSession(sessionId);
    const runBulkWriteWithFallback = async (operations, label) => {
        if (!operations.length) return;
        try {
            await collection.bulkWrite(operations, { ordered: true, writeConcern: { w: 'majority', wtimeout: 10000 } });
            return;
        } catch (bulkError) {
            console.error('[auth-store-bulk-write]', { sessionId, label, error: bulkError?.message || String(bulkError) });
        }
        const failures = [];
        for (const operation of operations) {
            try {
                if (operation.deleteOne) await collection.deleteOne(operation.deleteOne.filter);
                else if (operation.updateOne) await collection.updateOne(operation.updateOne.filter, operation.updateOne.update, { upsert: true, writeConcern: { w: 'majority', wtimeout: 10000 } });
            } catch (error) {
                failures.push(error?.message || String(error));
            }
        }
        if (failures.length) {
            console.error('[auth-store-write-failed]', { sessionId, label, failedOperations: failures.length, error: failures.slice(0, 3) });
            throw new Error(`auth_store_write_failed:${label}:${failures.length}`);
        }
    };
    const migrateLegacyCategoryInQueue = async type => {
        if (migratedLegacyCategories.has(type)) return;
        const markerId = `${sessionKey}_migration_${type}_v1`;
        const marker = await collection.findOne({ _id: markerId }, { projection: { _id: 1 } });
        if (marker) {
            migratedLegacyCategories.add(type);
            return;
        }
        const legacyId = `${sessionKey}_key_${type}`;
        const legacyDoc = await collection.findOne({ _id: legacyId });
        const legacyData = legacyDoc?.data;
        if (!legacyData || typeof legacyData !== 'object' || Array.isArray(legacyData)) {
            await collection.updateOne({ _id: markerId }, { $setOnInsert: { migrated: false, updatedAt: new Date() } }, { upsert: true });
            migratedLegacyCategories.add(type);
            return;
        }
        const operations = [];
        for (const [id, value] of Object.entries(legacyData)) {
            if (value === null || value === undefined) continue;
            const targetId = `${sessionKey}_key_${type}-${id}`;
            const migratedValue = normalizeSignalKeyValue(type, value);
            if ((type === 'session' && !migratedValue) || (isBinarySignalKeyCategory(type) && (!Buffer.isBuffer(migratedValue) || migratedValue.length === 0))) {
                console.warn('[auth-store-legacy-signal-key-skipped]', { sessionId, type, keyHash: shortLogHash(id), ...describeSignalSessionValue(value), action: 'preserve_legacy_document_without_migrating_invalid_signal_value' });
                continue;
            }
            operations.push({ updateOne: { filter: { _id: targetId }, update: { $setOnInsert: { data: migratedValue } }, upsert: true } });
        }
        await runBulkWriteWithFallback(operations, `legacy-key-migration-${type}`);
        await collection.updateOne({ _id: markerId }, { $setOnInsert: { migrated: true, keyCount: operations.length, updatedAt: new Date() } }, { upsert: true });
        migratedLegacyCategories.add(type);
        console.info('[auth-store-legacy-migrated-preserved]', { sessionId, type, keys: operations.length });
    };
    const keyStore = {
        get: async (type, ids) => queueAuthWrite(async () => {
            const result = {};
            if (!Array.isArray(ids) || ids.length === 0) return result;
            await migrateLegacyCategoryInQueue(type);
            const prefix = `${sessionKey}_key_${type}-`;
            const dbIds = ids.map(id => `${prefix}${id}`);
            const docs = await collection.find({ _id: { $in: dbIds } }).toArray();
            for (const doc of docs) {
                const keyId = doc._id.substring(prefix.length);
                let restored = normalizeSignalKeyValue(type, doc.data);
                if (type === 'session' && !restored) {
                    const storedShape = doc.data && typeof doc.data === 'object' ? Object.keys(doc.data).slice(0, 16) : [];
                    console.warn('[signal-auth-session-record-invalid-preserved]', { sessionId, category: type, keyHash: shortLogHash(keyId), ...describeSignalSessionValue(doc.data), storedShape, reason: 'session_record_requires_structured_sessions_object', action: 'preserve_record_and_skip_invalid_value' });
                    continue;
                }
                if (isBinarySignalKeyCategory(type) && (!Buffer.isBuffer(restored) || restored.length === 0)) {
                    const storedShape = doc.data && typeof doc.data === 'object' ? Object.keys(doc.data).slice(0, 16) : [];
                    console.warn('[signal-auth-binary-key-record-invalid-preserved]', { sessionId, category: type, keyHash: shortLogHash(keyId), ...describeSignalSessionValue(doc.data), storedShape, reason: 'signal_key_record_cannot_be_restored_as_nonempty_binary', action: 'preserve_record_and_skip_until_valid_binary_representation_is_available' });
                    continue;
                }
                if (isBinarySignalKeyCategory(type) && Buffer.isBuffer(restored) && !Buffer.isBuffer(doc.data) && doc.data?._bsontype !== 'Binary') {
                    await collection.updateOne({ _id: doc._id }, { $set: { data: restored, normalizedAt: new Date() } }, { writeConcern: { w: 'majority', wtimeout: 10000 } });
                    console.info('[signal-auth-record-normalized]', { sessionId, keyHash: shortLogHash(keyId), category: type, byteLength: restored.length });
                } else if (type === 'session' && (Buffer.isBuffer(doc.data) || doc.data instanceof Uint8Array || typeof doc.data === 'string')) {
                    await collection.updateOne({ _id: doc._id }, { $set: { data: restored, normalizedAt: new Date() } }, { writeConcern: { w: 'majority', wtimeout: 10000 } });
                    console.info('[signal-auth-session-record-normalized]', { sessionId, keyHash: shortLogHash(keyId), category: type, version: restored.version || null, sessionCount: Object.keys(restored._sessions || {}).length });
                }
                result[keyId] = restored;
            }
            return result;
        }),
        set: async data => queueAuthWrite(async () => {
            if (!data || typeof data !== 'object') return;
            const categories = Object.entries(data).filter(([, entries]) => entries && typeof entries === 'object' && !Array.isArray(entries));
            for (const [type] of categories) await migrateLegacyCategoryInQueue(type);
            const operations = [];
            for (const [type, entries] of categories) {
                for (const [id, value] of Object.entries(entries)) {
                    const dbId = `${sessionKey}_key_${type}-${id}`;
                    if (value === null || value === undefined) operations.push({ deleteOne: { filter: { _id: dbId } } });
                    else {
                        const storedValue = normalizeSignalKeyValue(type, value);
                        if (type === 'session' && !storedValue) {
                            console.error('[signal-auth-session-record-write-rejected]', { sessionId, category: type, keyHash: shortLogHash(id), ...describeSignalSessionValue(value), reason: 'session_record_requires_structured_sessions_object', action: 'reject_without_corrupting_existing_record' });
                            throw new Error('signal_auth_session_record_write_invalid');
                        }
                        if (isBinarySignalKeyCategory(type) && (!Buffer.isBuffer(storedValue) || storedValue.length === 0)) {
                            const binaryKeyError = `signal_auth_${type.replace(/[^a-z0-9_-]/gi, '')}_write_not_binary`;
                            console.error('[signal-auth-binary-key-write-rejected]', { sessionId, category: type, keyHash: shortLogHash(id), ...describeSignalSessionValue(value), reason: 'signal_key_record_must_be_nonempty_binary', acceptedConversions: ['Uint8Array', 'Buffer', 'BSON Binary', 'BufferJSON', 'serialized byte arrays'], action: 'reject_without_corrupting_existing_record' });
                            throw new Error(binaryKeyError);
                        }
                        operations.push({ updateOne: { filter: { _id: dbId }, update: { $set: { data: storedValue, updatedAt: new Date() } }, upsert: true } });
                    }
                }
            }
            await runBulkWriteWithFallback(operations, 'signal-keys');
        }),
        transaction: (operation, transactionKey) => {
            if (typeof operation !== 'function') return Promise.reject(new Error('signal_auth_store_transaction_callback_required'));
            return queueAuthTransaction(transactionKey, operation);
        }
    };
    const saveCreds = async () => {
        const retryDelays = [0, 350, 900, 1800];
        let lastError = null;
        for (let attempt = 0; attempt < retryDelays.length; attempt++) {
            if (retryDelays[attempt]) await new Promise(resolve => setTimeout(resolve, retryDelays[attempt]));
            try {
                const snapshot = fixBuffers(creds);
                await queueAuthWrite(() => collection.updateOne(
                    { _id: credsId },
                    { $set: { creds: snapshot, updatedAt: new Date() } },
                    { upsert: true, writeConcern: { w: 'majority', wtimeout: 10000 } }
                ));
                console.info('[auth-store-creds-write-completed]', { sessionId, attempt: attempt + 1, registered: !!creds?.registered, accountIdentityKnown: !!(getAuthenticatedPhoneNumber(authSocket?.user, creds) || getAuthenticatedLid(authSocket?.user, creds)) });
                return true;
            } catch (error) {
                lastError = error;
                const nonRetryable = /runtime_lock|duplicate_account|session_not_exists|fenced/i.test(String(error?.message || ''));
                console.error('[auth-store-creds-write-failed]', { sessionId, attempt: attempt + 1, retryable: !nonRetryable && attempt < retryDelays.length - 1, error: error?.message || String(error) });
                if (nonRetryable) break;
            }
        }
        if (lastError) throw lastError;
        return false;
    };
    return { state: { creds, keys: keyStore, setAuthSocket, flushAuthWrites }, saveCreds, flushAuthWrites };
}
async function deleteMongoSession(sessionId) {
    clearPairingChallengeTimer(sessionId);
    clearExplicitLogoutDeletionTimer(sessionId);
    try {
        if (!db || !sessionId) throw new Error('session_delete_database_or_id_unavailable');
        const now = new Date();
        const ownerRecord = await db.collection('session_owners').findOne({ sessionId }, { projection: { ownerInstanceId: 1, ownerLeaseUntil: 1, connectionStatus: 1 } }).catch(() => null);
        const ownerLeaseUntil = new Date(ownerRecord?.ownerLeaseUntil || 0).getTime();
        if (TFBOT_CLUSTER_ENABLED && ownerRecord?.ownerInstanceId && ownerRecord.ownerInstanceId !== TFBOT_CLUSTER_INSTANCE_ID && ownerLeaseUntil > now.getTime()) throw new Error('session_delete_blocked_by_foreign_owner_lease');
        const [foreignSessionLock, foreignAccountLock] = await Promise.all([
            db.collection('session_runtime_locks').findOne({ _id: sessionId, owner: { $ne: processInstanceId }, leaseUntil: { $gt: now } }, { projection: { owner: 1 } }).catch(() => null),
            db.collection('session_account_runtime_locks').findOne({ sessionId, owner: { $ne: processInstanceId }, leaseUntil: { $gt: now } }, { projection: { owner: 1 } }).catch(() => null)
        ]);
        if (foreignSessionLock || foreignAccountLock) throw new Error('session_delete_blocked_by_foreign_runtime_lock');
        const currentRuntime = activeSessions.get(sessionId);
        if (currentRuntime?.sock && isAuthenticatedSocketOperational(currentRuntime, currentRuntime.sock) && !['reauth_required', 'duplicate_account', 'deconnecte'].includes(String(currentRuntime.status || '').toLowerCase())) throw new Error('session_delete_blocked_while_socket_authenticated');
        await releaseSessionRuntimeLock(sessionId);
        const collection = db.collection('baileys_auth');
        const sessionKey = `auth-${sessionId}`;
        await collection.deleteMany({ _id: { $regex: `^${sessionKey}` } });
        await Promise.all([
            db.collection('session_owners').deleteMany({ sessionId }),
            db.collection('session_runtime_locks').deleteMany({ _id: sessionId, owner: processInstanceId }),
            db.collection('session_account_runtime_locks').deleteMany({ sessionId, owner: processInstanceId }),
            db.collection('user_preferences').deleteMany({ sessionId }),
            db.collection('processed_messages').deleteMany({ sessionId }),
            db.collection('baileys_outgoing_messages').deleteMany({ sessionId }),
            db.collection('baileys_quoted_messages').deleteMany({ sessionId }),
            db.collection('lid_phone_mappings').deleteMany({ sessionId }),
            db.collection('lid_phone_mappings').deleteMany({ _id: { $regex: `^${String(sessionId).replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}:` } }),
            db.collection('group_settings').deleteMany({ sessionId }),
            db.collection('group_del2').deleteMany({ sessionId }),
            db.collection('group_del3').deleteMany({ sessionId })
        ]);
        sessionOwnersCache.delete(sessionId);
        activeSessions.delete(sessionId);
        cleanupSessionVolatileCaches(sessionId);
        console.info('[session-data-cleanup-completed]', { sessionId, removed: ['auth', 'owner', 'user_preferences', 'processed_messages', 'outgoing_retry_messages', 'lid_mappings', 'group_settings', 'group_del2', 'group_del3'], localVolatileCachesCleared: true });
    } catch (error) {
        console.error('[session-delete-failed]', { sessionId, error: error?.message || String(error) });
        throw error;
    }
}


function clearPairingChallengeTimer(sessionId) {
    const timer = pairingChallengeTimers.get(sessionId);
    if (timer) clearTimeout(timer);
    pairingChallengeTimers.delete(sessionId);
}

function clearExplicitLogoutDeletionTimer(sessionId) {
    const timer = explicitLogoutDeletionTimers.get(sessionId);
    if (timer) clearTimeout(timer);
    explicitLogoutDeletionTimers.delete(sessionId);
}

function isTfbotAuthenticatedIdentityPresent(runtime, credentials, owner = null) {
    const liveUser = runtime?.sock?.user || null;
    return !!(
        credentials?.registered === true ||
        credentials?.me?.id || credentials?.me?.lid ||
        getAuthenticatedPhoneNumber(liveUser, credentials) ||
        getAuthenticatedLid(liveUser, credentials)
    );
}

function hasEstablishedWhatsAppAccount(owner, runtime, credentials) {
    const ownerStatus = String(owner?.connectionStatus || owner?.status || '').toLowerCase();
    return credentials?.registered === true
        || !!(runtime?.sock && isAuthenticatedSocketOperational(runtime, runtime.sock))
        || !!owner?.connectedSince
        || !!owner?.socketAuthenticatedAt
        || owner?.socketAuthenticated === true
        || owner?.everAuthenticated === true
        || owner?.everConnected === true
        || (['connected', 'connecte', 'active', 'online'].includes(ownerStatus) && String(owner?.lastWhatsAppEvent || '').toLowerCase() === 'open');
}

async function waitForExpiredPairingAuthQueue(sessionId, timeoutMs = 5000) {
    const key = String(sessionId || '');
    const deadline = Date.now() + Math.max(500, Number(timeoutMs) || 5000);
    while (Date.now() < deadline) {
        const pending = authWriteQueues.get(key);
        if (!pending) {
            authWriteFailures.delete(key);
            return true;
        }
        let settled = false;
        try {
            await promiseWithTimeout(pending, Math.max(100, Math.min(1000, deadline - Date.now())), 'expired pairing auth queue settlement');
            settled = true;
        } catch (error) {
            if (/timed out|timeout/i.test(String(error?.message || error))) return false;
            settled = true;
        }
        if (settled && authWriteQueues.get(key) === pending) {
            authWriteQueues.delete(key);
            authWriteFailures.delete(key);
            authWriteActivityAt.set(key, Date.now());
        }
    }
    return !authWriteQueues.has(key);
}

async function expireUnregisteredPairingSession(owner, source = 'pairing_challenge_expired') {
    const sessionId = String(owner?.sessionId || '').trim();
    if (!db || !sessionId) return { removed: false, reason: 'database_or_session_unavailable' };
    const ownerCol = db.collection('session_owners');
    const liveOwner = owner || await ownerCol.findOne({ sessionId }).catch(() => null);
    if (!liveOwner) return { removed: false, reason: 'owner_record_missing' };
    const runtime = activeSessions.get(sessionId);
    const authDoc = await db.collection('baileys_auth').findOne({ _id: `auth-${sessionId}-creds` }, { projection: { 'creds.registered': 1, 'creds.me.id': 1, 'creds.me.lid': 1 } }).catch(() => null);
    const credentials = runtime?.authState?.creds || authDoc?.creds || null;
    if (hasEstablishedWhatsAppAccount(liveOwner, runtime, credentials)) {
        clearPairingChallengeTimer(sessionId);
        pairingSessionsBeingExpired.delete(sessionId);
        await ownerCol.updateOne({ sessionId }, { $set: { pairingPending: false, pairingAttemptPending: false, pairingCleanupPending: false, updatedAt: new Date() }, $unset: { pairingChallengeStartedAt: 1, pairingExpiredAt: 1, lastRestoreError: 1, lastRestoreErrorHash: 1, nextRestoreRetryAt: 1 } }).catch(() => {});
        return { removed: false, preserved: true, reason: 'authenticated_or_previously_connected_account' };
    }
    const now = Date.now();
    const ownerLeaseUntil = new Date(liveOwner.ownerLeaseUntil || 0).getTime();
    if (TFBOT_CLUSTER_ENABLED && liveOwner.ownerInstanceId && liveOwner.ownerInstanceId !== TFBOT_CLUSTER_INSTANCE_ID && ownerLeaseUntil > now) return { removed: false, reason: 'foreign_owner_lease_active' };
    const [sessionLock, accountLock] = await Promise.all([
        db.collection('session_runtime_locks').findOne({ _id: sessionId, leaseUntil: { $gt: new Date(now) } }, { projection: { owner: 1 } }).catch(() => null),
        db.collection('session_account_runtime_locks').findOne({ sessionId, leaseUntil: { $gt: new Date(now) } }, { projection: { owner: 1 } }).catch(() => null)
    ]);
    if ([sessionLock, accountLock].some(lock => lock && lock.owner !== processInstanceId)) return { removed: false, reason: 'foreign_runtime_lock_active' };
    pairingSessionsBeingExpired.add(sessionId);
    clearPairingChallengeTimer(sessionId);
    const reconnectTimer = reconnectTimers.get(sessionId);
    if (reconnectTimer) clearTimeout(reconnectTimer);
    reconnectTimers.delete(sessionId);
    reconnectRetryDueAt.delete(sessionId);
    const lockRetryTimer = sessionLockRetryTimers.get(sessionId);
    if (lockRetryTimer) clearTimeout(lockRetryTimer);
    sessionLockRetryTimers.delete(sessionId);
    sessionLockRetryDueAt.delete(sessionId);
    sessionLockRetryAttempts.delete(sessionId);
    if (runtime) {
        runtime.status = 'pairing_expired';
        runtime.active = false;
        runtime.qrString = null;
        runtime.qrSocket = null;
        runtime.qrReceivedAt = 0;
        runtime.pairingAttemptPending = false;
        runtime.pairingExpiredAt = now;
        runtime.lastRestoreError = null;
        runtime.lastDisconnectCode = null;
        runtime.lastDisconnectReason = null;
    }
    await ownerCol.updateOne({ sessionId }, { $set: { connectionStatus: 'pairing_expired', pairingPending: false, pairingAttemptPending: false, pairingExpiredAt: new Date(now), pairingCleanupPending: true, socketAuthenticated: false, socketReady: false, statusUpdatedAt: new Date(now), updatedAt: new Date(now) }, $unset: { pairingChallengeStartedAt: 1, lastRestoreError: 1, lastRestoreErrorHash: 1, nextRestoreRetryAt: 1, lastDisconnectCode: 1, lastDisconnectReason: 1 } }).catch(() => {});
    if (runtime?.sock) {
        let socketCleaned = false;
        try { socketCleaned = await cleanupSocket(sessionId); } catch (error) { socketCleaned = false; }
        if (!socketCleaned && runtime.sock) return { removed: false, pending: true, reason: 'socket_close_not_confirmed' };
    }
    await releaseSessionRuntimeLock(sessionId).catch(() => {});
    await db.collection('session_account_runtime_locks').deleteMany({ sessionId, owner: processInstanceId }).catch(() => {});
    await db.collection('session_runtime_locks').deleteMany({ _id: sessionId, owner: processInstanceId }).catch(() => {});
    const queueSettled = await waitForExpiredPairingAuthQueue(sessionId, 5000);
    if (!queueSettled) return { removed: false, pending: true, reason: 'auth_write_queue_still_running' };
    try {
        await deleteMongoSession(sessionId);
        pairingSessionsBeingExpired.delete(sessionId);
        console.info('[pairing-challenge-expired-and-deleted]', { sessionId, source, ttlMs: PAIRING_CHALLENGE_TTL_MS, authDataDeleted: true, reason: 'unregistered_pairing_challenge_expired_without_authenticated_account' });
        return { removed: true, reason: 'expired_unregistered_pairing' };
    } catch (error) {
        console.warn('[pairing-challenge-expiry-delete-failed]', { sessionId, source, error: error?.message || String(error) });
        return { removed: false, pending: true, reason: error?.message || 'delete_failed' };
    }
}

function schedulePairingChallengeExpiry(sessionId, challengeStartedAt, source = 'pairing_request') {
    clearPairingChallengeTimer(sessionId);
    const startedAt = new Date(challengeStartedAt || Date.now()).getTime();
    const remaining = Math.max(0, PAIRING_CHALLENGE_TTL_MS - Math.max(0, Date.now() - (Number.isFinite(startedAt) ? startedAt : Date.now())));
    const timer = setTimeout(async () => {
        pairingChallengeTimers.delete(sessionId);
        try {
            const owner = await db.collection('session_owners').findOne({ sessionId }, { projection: { pairingPending: 1, pairingAttemptPending: 1, pairingChallengeStartedAt: 1, pairingStartedAt: 1, pairingCleanupPending: 1, ownerInstanceId: 1, ownerLeaseUntil: 1, connectedSince: 1, socketAuthenticatedAt: 1, AccountJid: 1, OwnerLid: 1, Number: 1 } }).catch(() => null);
            if (!owner || (owner.pairingAttemptPending !== true && owner.pairingCleanupPending !== true)) return;
            const ownerChallengeAt = new Date(owner.pairingChallengeStartedAt || owner.pairingStartedAt || 0).getTime();
            if (owner.pairingCleanupPending !== true && ownerChallengeAt && Math.abs(ownerChallengeAt - startedAt) > 1500) return;
            if (owner.pairingCleanupPending !== true && ownerChallengeAt && Date.now() - ownerChallengeAt < PAIRING_CHALLENGE_TTL_MS) {
                schedulePairingChallengeExpiry(sessionId, ownerChallengeAt, source);
                return;
            }
            await expireUnregisteredPairingSession(owner, source);
        } catch (error) {
            console.warn('[pairing-challenge-expiry-failed]', { sessionId, source, error: error?.message || String(error) });
        }
    }, remaining);
    if (typeof timer.unref === 'function') timer.unref();
    pairingChallengeTimers.set(sessionId, timer);
    return timer;
}

async function retireRevokedWhatsAppSession(sessionId, reason = 'whatsapp_reauthentication_required') {
    if (!db || !sessionId) return { retired: false, reason: 'database_or_session_unavailable' };
    const ownerCollection = db.collection('session_owners');
    const owner = await ownerCollection.findOne({ sessionId }, { projection: { reauthRequired: 1, connectionStatus: 1, ownerInstanceId: 1, ownerLeaseUntil: 1, lastAuthFailure: 1, lastDisconnectReason: 1, format: 1, Format: 1 } }).catch(() => null);
    if (!owner || owner.reauthRequired !== true || String(owner.connectionStatus || '').toLowerCase() !== 'reauth_required') return { retired: false, reason: 'session_no_longer_requires_reauthentication' };
    const now = Date.now();
    const ownerLeaseUntil = new Date(owner.ownerLeaseUntil || 0).getTime();
    if (TFBOT_CLUSTER_ENABLED && owner.ownerInstanceId && owner.ownerInstanceId !== TFBOT_CLUSTER_INSTANCE_ID && ownerLeaseUntil > now) return { retired: false, reason: 'foreign_owner_lease_active' };
    const [sessionLock, accountLock] = await Promise.all([
        db.collection('session_runtime_locks').findOne({ _id: sessionId, leaseUntil: { $gt: new Date(now) } }, { projection: { owner: 1 } }).catch(() => null),
        db.collection('session_account_runtime_locks').findOne({ sessionId, leaseUntil: { $gt: new Date(now) } }, { projection: { owner: 1 } }).catch(() => null)
    ]);
    if ([sessionLock, accountLock].some(lock => lock && lock.owner !== processInstanceId)) return { retired: false, reason: 'foreign_runtime_lock_active' };
    const conflictReason = String(owner.lastAuthFailure || owner.lastDisconnectReason || '');
    const transientConflict = /\bconflict\b|connection[\s_-]*replaced|stream errored.*conflict|replaced by another connection/i.test(conflictReason);
    if (transientConflict) {
        const authRecord = await db.collection('baileys_auth').findOne({ _id: `auth-${sessionId}-creds` }, { projection: { 'creds.registered': 1, 'creds.me.id': 1, 'creds.me.lid': 1, 'creds.me.name': 1 } }).catch(() => null);
        if (hasAuthenticatedWhatsAppCredentials(authRecord?.creds)) {
            if (!await waitForExpiredPairingAuthQueue(sessionId, 5000)) return { retired: false, pending: true, reason: 'auth_write_queue_still_running_during_conflict_recovery' };
            const runtime = activeSessions.get(sessionId);
            const stillAuthenticated = !!(runtime?.sock && isAuthenticatedSocketOperational(runtime, runtime.sock));
            if (runtime?.sock && !stillAuthenticated) {
                const closed = await cleanupSocket(sessionId).catch(() => false);
                if (!closed && runtime.sock) return { retired: false, pending: true, reason: 'conflicted_socket_close_not_confirmed' };
            }
            const conflictRecoveredAt = new Date();
            const phone = getAuthenticatedPhoneNumber(runtime?.sock?.user || null, runtime?.authState?.creds || authRecord.creds);
            const recoverySet = {
                credentialsRevoked: false,
                socketAuthenticated: stillAuthenticated,
                socketReady: stillAuthenticated && isWhatsAppSocketReady(runtime, runtime.sock),
                connectionStatus: stillAuthenticated ? 'connected' : 'reconnexion',
                reauthRequired: false,
                pairingPending: false,
                pairingAttemptPending: false,
                lastWhatsAppEvent: stillAuthenticated ? 'open' : 'close',
                lastWhatsAppEventAt: conflictRecoveredAt,
                statusUpdatedAt: conflictRecoveredAt,
                updatedAt: conflictRecoveredAt,
                ...(phone ? { Number: phone } : {}),
                ...(!stillAuthenticated ? { nextRestoreRetryAt: new Date(Date.now() + 1200) } : {})
            };
            const recovered = await ownerCollection.updateOne(
                { sessionId, reauthRequired: true, connectionStatus: 'reauth_required' },
                { $set: recoverySet, $unset: { credentialsRevokedAt: 1, lastAuthFailure: 1, lastAuthFailureAt: 1, lastDisconnectCode: 1, lastDisconnectReason: 1, lastRestoreError: 1, lastRestoreErrorHash: 1, ownerInstanceId: 1, ownerInstanceUrl: 1, ownerLeaseUntil: 1 } }
            );
            if (recovered.matchedCount) {
                await releaseSessionRuntimeLock(sessionId).catch(() => {});
                await db.collection('session_runtime_locks').deleteMany({ _id: sessionId, owner: processInstanceId }).catch(() => {});
                await db.collection('session_account_runtime_locks').deleteMany({ sessionId, owner: processInstanceId }).catch(() => {});
                if (runtime) {
                    runtime.reauthRequired = false;
                    runtime.active = stillAuthenticated;
                    runtime.status = stillAuthenticated ? 'connecte' : 'deconnecte';
                    runtime.lastDisconnectCode = null;
                    runtime.lastDisconnectReason = null;
                    runtime.lastRestoreError = null;
                    runtime.lastWhatsAppEvent = stillAuthenticated ? 'open' : 'close';
                    runtime.lastWhatsAppEventAt = conflictRecoveredAt.getTime();
                    if (!stillAuthenticated && !serverShuttingDown && !tfbotWorkerStopping && (!TFBOT_CLUSTER_ENABLED || tfbotWorkerActive)) scheduleSessionReconnect(sessionId, false, normalizeConnectionFormat(owner.format || owner.Format || runtime.format || 'pair'));
                } else if (!stillAuthenticated && !serverShuttingDown && !tfbotWorkerStopping && (!TFBOT_CLUSTER_ENABLED || tfbotWorkerActive)) {
                    void startAdamBot(sessionId, false, normalizeConnectionFormat(owner.format || owner.Format || 'pair'), true).catch(error => console.warn('[transient-conflict-session-restart-failed]', { sessionId, error: error?.message || String(error) }));
                }
                sessionOwnersCache.delete(sessionId);
                scheduleSessionListBroadcast('transient_conflict_credentials_recovered');
                console.warn('[transient-conflict-session-recovered-with-preserved-auth]', { sessionId, authDocumentsDeleted: false, credentialsStillRegistered: true, socketAlreadyOperational: stillAuthenticated, reconnectScheduled: !stillAuthenticated });
                return { retired: false, recovered: true, reason: 'transient_conflict_credentials_preserved' };
            }
            return { retired: false, reason: 'conflict_recovery_state_changed' };
        }
    }
    const runtime = activeSessions.get(sessionId);
    if (runtime?.sock) {
        const closed = await cleanupSocket(sessionId).catch(() => false);
        if (!closed && runtime.sock) return { retired: false, pending: true, reason: 'socket_close_not_confirmed' };
    }
    if (!await waitForExpiredPairingAuthQueue(sessionId, 5000)) return { retired: false, pending: true, reason: 'auth_write_queue_still_running' };
    await releaseSessionRuntimeLock(sessionId).catch(() => {});
    await db.collection('session_runtime_locks').deleteMany({ _id: sessionId, owner: processInstanceId }).catch(() => {});
    await db.collection('session_account_runtime_locks').deleteMany({ sessionId, owner: processInstanceId }).catch(() => {});
    const escapedSessionId = String(sessionId).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    await db.collection('baileys_auth').deleteMany({ _id: { $regex: `^auth-${escapedSessionId}` } });
    await ownerCollection.updateOne(
        { sessionId, reauthRequired: true, connectionStatus: 'reauth_required' },
        { $set: { credentialsRevoked: true, credentialsRevokedAt: new Date(now), socketAuthenticated: false, socketReady: false, pairingPending: false, pairingAttemptPending: false, updatedAt: new Date(now) }, $unset: { ownerInstanceId: 1, ownerInstanceUrl: 1, ownerLeaseUntil: 1, nextRestoreRetryAt: 1, lastRestoreError: 1, lastRestoreErrorHash: 1 } }
    );
    activeSessions.delete(sessionId);
    sessionOwnersCache.delete(sessionId);
    cleanupSessionVolatileCaches(sessionId);
    console.info('[whatsapp-revoked-device-auth-cleared-settings-preserved]', { sessionId, reason, authDocumentsDeleted: true, ownerRecordPreserved: true, userPreferencesPreserved: true, groupSettingsPreserved: true, status: 'reauth_required' });
    return { retired: true, reason: 'revoked_auth_cleared_settings_preserved' };
}

function scheduleExplicitLogoutDeletion(sessionId, logoutAt, reason = 'logged_out') {
    clearExplicitLogoutDeletionTimer(sessionId);
    const expectedAt = new Date(logoutAt || Date.now()).getTime();
    const timer = setTimeout(async () => {
        explicitLogoutDeletionTimers.delete(sessionId);
        try {
            const owner = await db.collection('session_owners').findOne({ sessionId }, { projection: { reauthRequired: 1, connectionStatus: 1, lastAuthFailureAt: 1, ownerInstanceId: 1, ownerLeaseUntil: 1 } }).catch(() => null);
            if (!owner || owner.reauthRequired !== true || String(owner.connectionStatus || '').toLowerCase() !== 'reauth_required') return;
            const savedLogoutAt = new Date(owner.lastAuthFailureAt || 0).getTime();
            if (!Number.isFinite(savedLogoutAt) || Math.abs(savedLogoutAt - expectedAt) > 1500) return;
            const runtime = activeSessions.get(sessionId);
            if (runtime?.sock && isAuthenticatedSocketOperational(runtime, runtime.sock)) {
                console.warn('[explicit-logout-deletion-cancelled-authenticated-runtime]', { sessionId, reason: 'a_new_authenticated_socket_is_already_active' });
                return;
            }
            const reconnectTimer = reconnectTimers.get(sessionId);
            if (reconnectTimer) clearTimeout(reconnectTimer);
            reconnectTimers.delete(sessionId);
            const retirement = await retireRevokedWhatsAppSession(sessionId, reason);
            if (!retirement.retired) console.info('[explicit-whatsapp-reauth-cleanup-pending]', { sessionId, reason, cleanupReason: retirement.reason || 'not_retired', retryInMs: 15000 });
        } catch (error) {
            console.warn('[explicit-whatsapp-logout-session-deletion-failed]', { sessionId, reason, error: error?.message || String(error) });
        }
    }, EXPLICIT_LOGOUT_CLEANUP_DELAY_MS);
    if (typeof timer.unref === 'function') timer.unref();
    explicitLogoutDeletionTimers.set(sessionId, timer);
    return timer;
}

async function cleanupExpiredPairingChallenges() {
    if (!db || serverShuttingDown || (TFBOT_CLUSTER_ENABLED && !tfbotWorkerActive) || tfbotWorkerStopping) return 0;
    const now = Date.now();
    const cutoff = new Date(now - PAIRING_CHALLENGE_TTL_MS);
    const pairingStatuses = ['pairing_starting', 'pairing', 'qr_disponible', 'synchronisation', 'synchronizing', 'initialisation', 'connecting', 'opening'];
    const candidates = await db.collection('session_owners').find({ $or: [
        { pairingPending: true, $or: [
            { pairingAttemptPending: true, pairingChallengeStartedAt: { $lte: cutoff } },
            { pairingAttemptPending: { $ne: false }, pairingStartedAt: { $lte: cutoff }, connectionStatus: { $in: pairingStatuses } }
        ] },
        { pairingCleanupPending: true, connectionStatus: 'pairing_expired' },
        { format: { $in: ['qr', 'pair', 'code'] }, connectionStatus: { $nin: ['connected', 'connecte'] }, createdAt: { $lte: cutoff } },
        { Format: { $in: ['qr', 'pair', 'code'] }, connectionStatus: { $nin: ['connected', 'connecte'] }, createdAt: { $lte: cutoff } },
        { PairingNumber: { $exists: true, $nin: ['', null] }, connectionStatus: { $nin: ['connected', 'connecte'] }, pairingStartedAt: { $lte: cutoff } }
    ] }).limit(500).toArray().catch(() => []);
    let removed = 0;
    for (const owner of candidates) {
        const sessionId = String(owner.sessionId || '');
        if (!sessionId) continue;
        const idTimestamp = Number(String(sessionId).match(/^session_(\d+)/)?.[1] || 0);
        const challengeAt = [owner.pairingChallengeStartedAt, owner.pairingStartedAt, owner.createdAt, idTimestamp].map(value => value instanceof Date ? value.getTime() : Number.isFinite(Number(value)) && Number(value) > 0 ? Number(value) : new Date(value || 0).getTime()).find(value => Number.isFinite(value) && value > 0) || 0;
        if (owner.pairingCleanupPending !== true && (!Number.isFinite(challengeAt) || challengeAt <= 0 || now - challengeAt < PAIRING_CHALLENGE_TTL_MS)) continue;
        const result = await expireUnregisteredPairingSession(owner, 'periodic_pairing_challenge_cleanup');
        if (result?.removed) removed++;
    }
    return removed;
}

async function cleanupExpiredExplicitLogoutSessions() {
    if (!db || serverShuttingDown || (TFBOT_CLUSTER_ENABLED && !tfbotWorkerActive) || tfbotWorkerStopping) return 0;
    const now = Date.now();
    const cutoff = new Date(now - EXPLICIT_LOGOUT_CLEANUP_DELAY_MS);
    const candidates = await db.collection('session_owners').find({ reauthRequired: true, connectionStatus: 'reauth_required', lastAuthFailureAt: { $lte: cutoff } }).limit(100).toArray().catch(() => []);
    let removed = 0;
    for (const owner of candidates) {
        const sessionId = String(owner.sessionId || '');
        if (!sessionId) continue;
        const runtime = activeSessions.get(sessionId);
        if (runtime?.sock && isAuthenticatedSocketOperational(runtime, runtime.sock)) continue;
        try {
            const retirement = await retireRevokedWhatsAppSession(sessionId, 'reauthentication_cleanup_after_restart');
            if (retirement.retired) removed++;
            else console.info('[explicit-logout-restart-cleanup-pending]', { sessionId, cleanupReason: retirement.reason || 'not_retired' });
        } catch (error) {
            console.warn('[explicit-logout-restart-cleanup-failed]', { sessionId, error: error?.message || String(error) });
        }
    }
    return removed;
}


async function renameMongoSession(oldSessionId, newSessionId) {
    try {
        const collection = db.collection('baileys_auth');
        const oldKey = `auth-${oldSessionId}`;
        const newKey = `auth-${newSessionId}`;
        const oldDocs = await collection.find({ _id: { $regex: `^${oldKey}` } }).toArray();
        for (const doc of oldDocs) {
            const newId = doc._id.replace(oldKey, newKey);
            const { _id: ignoredId, ...documentData } = doc;
            await collection.updateOne({ _id: newId }, { $setOnInsert: documentData }, { upsert: true });
        }
        await collection.deleteMany({ _id: { $regex: `^${oldKey}` } });
        const ownerDoc = await db.collection('session_owners').findOne({ sessionId: oldSessionId });
        if (ownerDoc) {
            const { _id: ignoredOwnerId, ...ownerFields } = ownerDoc;
            await db.collection('session_owners').updateOne({ sessionId: newSessionId }, { $set: { ...ownerFields, sessionId: newSessionId } }, { upsert: true });
            await db.collection('session_owners').deleteOne({ sessionId: oldSessionId });
            sessionOwnersCache.set(newSessionId, { ...ownerFields, sessionId: newSessionId });
        }
        await db.collection('user_preferences').updateMany({ sessionId: oldSessionId }, { $set: { sessionId: newSessionId } });
        await db.collection('group_settings').updateMany({ sessionId: oldSessionId }, { $set: { sessionId: newSessionId } });
        await db.collection('group_del2').updateMany({ sessionId: oldSessionId }, { $set: { sessionId: newSessionId } });
        await db.collection('group_del3').updateMany({ sessionId: oldSessionId }, { $set: { sessionId: newSessionId } });
        await db.collection('processed_messages').deleteMany({ sessionId: oldSessionId });
        await db.collection('baileys_outgoing_messages').deleteMany({ sessionId: oldSessionId });
        await db.collection('baileys_quoted_messages').deleteMany({ sessionId: oldSessionId });
        await db.collection('lid_phone_mappings').deleteMany({ sessionId: oldSessionId });
        cleanupSessionVolatileCaches(oldSessionId);
        sessionOwnersCache.delete(oldSessionId);
        } catch (error) {
        console.error('[session-rename-failed]', { oldSessionId, newSessionId, error: error?.message || String(error) });
        throw error;
    }
}

async function mergeSessionScopedData(sourceSessionId, targetSessionId) {
    if (!db || !sourceSessionId || !targetSessionId || sourceSessionId === targetSessionId) return { migrated: false, reason: 'invalid_session_pair' };
    const ownerCollection = db.collection('session_owners');
    const sourceOwner = await ownerCollection.findOne({ sessionId: sourceSessionId });
    const targetOwner = await ownerCollection.findOne({ sessionId: targetSessionId });
    if (sourceOwner) {
        const ownerUpdates = {};
        const sourceMode = [sourceOwner.mode, sourceOwner.Mode, sourceOwner.botMode].map(value => String(value || '').trim()).find(Boolean);
        if (sourceMode) {
            ownerUpdates.mode = sourceMode;
            ownerUpdates.Mode = sourceMode;
            ownerUpdates.botMode = sourceMode;
        }
        const sourceLanguage = [sourceOwner.lang, sourceOwner.language, sourceOwner.Lang].map(value => String(value || '').trim()).find(Boolean);
        if (sourceLanguage) {
            ownerUpdates.lang = sourceLanguage;
            ownerUpdates.language = sourceLanguage;
        }
        for (const field of ['Name', 'name', 'ownerName', 'OwnerLid', 'ownerLid', 'AccountJid', 'accountJid', 'Number', 'number']) {
            const previous = sourceOwner[field];
            const current = targetOwner?.[field];
            if ((current === undefined || current === null || current === '') && previous !== undefined && previous !== null && previous !== '') ownerUpdates[field] = previous;
        }
        if (Object.keys(ownerUpdates).length) {
            await ownerCollection.updateOne(
                { sessionId: targetSessionId },
                { $set: ownerUpdates, $setOnInsert: { sessionId: targetSessionId, createdAt: sourceOwner.createdAt || new Date() } },
                { upsert: true }
            );
        }
    }
    const groupSettings = await db.collection('group_settings').find({ sessionId: sourceSessionId }).toArray();
    for (const source of groupSettings) {
        const selector = { sessionId: targetSessionId, gjid: source.gjid };
        const fields = Object.fromEntries(Object.entries(source).filter(([key]) => !['_id', 'sessionId', 'gjid', 'createdAt'].includes(key)));
        if (!Object.keys(fields).length) continue;
        await db.collection('group_settings').updateOne(
            selector,
            { $set: { ...fields, migratedFromSessionId: sourceSessionId }, $setOnInsert: { createdAt: source.createdAt || new Date() } },
            { upsert: true }
        );
    }
    const del2Targets = await db.collection('group_del2').find({ sessionId: sourceSessionId }).toArray();
    for (const source of del2Targets) {
        const selector = { sessionId: targetSessionId, gjid: source.gjid, targetJid: source.targetJid };
        const fields = Object.fromEntries(Object.entries(source).filter(([key]) => !['_id', 'sessionId', 'gjid', 'targetJid', 'createdAt'].includes(key)));
        await db.collection('group_del2').updateOne(
            selector,
            { $set: { ...fields, migratedFromSessionId: sourceSessionId }, $setOnInsert: { createdAt: source.createdAt || new Date() } },
            { upsert: true }
        );
    }
    const del3Rules = await db.collection('group_del3').find({ sessionId: sourceSessionId }).toArray();
    for (const source of del3Rules) {
        const selector = { sessionId: targetSessionId, gjid: source.gjid, messageFormat: source.messageFormat };
        const fields = Object.fromEntries(Object.entries(source).filter(([key]) => !['_id', 'sessionId', 'gjid', 'messageFormat', 'createdAt'].includes(key)));
        await db.collection('group_del3').updateOne(
            selector,
            { $set: { ...fields, migratedFromSessionId: sourceSessionId }, $setOnInsert: { createdAt: source.createdAt || new Date() } },
            { upsert: true }
        );
    }
    const preferences = await db.collection('user_preferences').find({ sessionId: sourceSessionId }).toArray();
    for (const source of preferences) {
        if (!source.sender) continue;
        const selector = { sessionId: targetSessionId, sender: source.sender };
        const fields = Object.fromEntries(Object.entries(source).filter(([key]) => !['_id', 'sessionId', 'sender', 'createdAt'].includes(key)));
        await db.collection('user_preferences').updateOne(
            selector,
            { $set: { ...fields, migratedFromSessionId: sourceSessionId }, $setOnInsert: { createdAt: source.createdAt || new Date() } },
            { upsert: true }
        );
    }
    const mappings = await db.collection('lid_phone_mappings').find({ sessionId: sourceSessionId }).toArray();
    for (const source of mappings) {
        const oldPrefix = `${sourceSessionId}:`;
        const oldId = String(source._id || '');
        const newId = oldId.startsWith(oldPrefix) ? `${targetSessionId}:${oldId.slice(oldPrefix.length)}` : `${targetSessionId}:${oldId.split(':').pop()}`;
        const existing = await db.collection('lid_phone_mappings').findOne({ _id: newId }, { projection: { updatedAt: 1 } });
        const sourceTime = new Date(source.updatedAt || source.createdAt || 0).getTime() || 0;
        const targetTime = new Date(existing?.updatedAt || 0).getTime() || 0;
        if (!existing || sourceTime >= targetTime) {
            const fields = Object.fromEntries(Object.entries(source).filter(([key]) => !['_id', 'createdAt'].includes(key)));
            await db.collection('lid_phone_mappings').updateOne(
                { _id: newId },
                { $set: { ...fields, sessionId: targetSessionId, lastSessionId: targetSessionId, migratedFromSessionId: sourceSessionId }, $setOnInsert: { createdAt: source.createdAt || new Date() } },
                { upsert: true }
            );
        }
    }
    cleanupSessionVolatileCaches(sourceSessionId);
    cleanupSessionVolatileCaches(targetSessionId);
    sessionOwnersCache.delete(sourceSessionId);
    sessionOwnersCache.delete(targetSessionId);
    console.info('[session-account-data-migrated]', { sourceSessionId, targetSessionId, groupSettings: groupSettings.length, del2Targets: del2Targets.length, del3Rules: del3Rules.length, userPreferences: preferences.length, lidPhoneMappings: mappings.length, sourceAccountSettingsPreferred: true, signalAuthKeysCopied: false, authStoreStrategy: 'keep_only_target_session_signal_keys' });
    return { migrated: true, groupSettings: groupSettings.length, del2Targets: del2Targets.length, del3Rules: del3Rules.length, userPreferences: preferences.length, lidPhoneMappings: mappings.length };
}

async function retireDuplicateAccountSession(sourceSessionId, targetSessionId, reason = 'same_authenticated_account_reconnected') {
    if (!db || !sourceSessionId || !targetSessionId || sourceSessionId === targetSessionId) return { retired: false, reason: 'invalid_session_pair' };
    const ownerCollection = db.collection('session_owners');
    const [sourceOwner, targetOwner, sourceCredsDoc, targetCredsDoc] = await Promise.all([
        ownerCollection.findOne({ sessionId: sourceSessionId }),
        ownerCollection.findOne({ sessionId: targetSessionId }),
        db.collection('baileys_auth').findOne({ _id: `auth-${sourceSessionId}-creds` }),
        db.collection('baileys_auth').findOne({ _id: `auth-${targetSessionId}-creds` })
    ]);
    if (!sourceOwner || !targetOwner) return { retired: false, reason: 'owner_record_missing' };
    const sourceCreds = sourceCredsDoc?.creds ? fixBuffers(sourceCredsDoc.creds) : null;
    const targetCreds = targetCredsDoc?.creds ? fixBuffers(targetCredsDoc.creds) : null;
    const sourceRuntime = activeSessions.get(sourceSessionId) || null;
    const targetRuntime = activeSessions.get(targetSessionId) || null;
    const sourcePhone = getAuthenticatedPhoneNumber(sourceRuntime?.sock?.user || null, sourceCreds) || normalizePhoneNumber(sourceOwner.Number || sourceOwner.number || sourceOwner.PairingNumber || '') || getAuthenticatedPhoneNumber({ id: sourceOwner.AccountJid || sourceOwner.accountJid || '' }, null);
    const targetPhone = getAuthenticatedPhoneNumber(targetRuntime?.sock?.user || null, targetCreds) || normalizePhoneNumber(targetOwner.Number || targetOwner.number || targetOwner.PairingNumber || '') || getAuthenticatedPhoneNumber({ id: targetOwner.AccountJid || targetOwner.accountJid || '' }, null);
    const sourceLid = getAuthenticatedLid(sourceRuntime?.sock?.user || null, sourceCreds) || normalizeLidCacheKey(sourceOwner.OwnerLid || sourceOwner.ownerLid || sourceOwner.AccountJid || sourceOwner.accountJid || '');
    const targetLid = getAuthenticatedLid(targetRuntime?.sock?.user || null, targetCreds) || normalizeLidCacheKey(targetOwner.OwnerLid || targetOwner.ownerLid || targetOwner.AccountJid || targetOwner.accountJid || '');
    if (targetCreds?.registered !== true || (!targetPhone && !targetLid)) return { retired: false, reason: 'target_account_not_authenticated' };
    const samePhone = !!(sourcePhone && targetPhone && sourcePhone === targetPhone);
    const sameLid = !!(sourceLid && targetLid && /@lid$/i.test(sourceLid) && sourceLid === targetLid);
    if (!samePhone && !sameLid) return { retired: false, reason: 'authenticated_account_identity_mismatch' };
    const now = new Date();
    const targetLockKey = normalizeAccountRuntimeLockKey(targetPhone || targetLid);
    const targetAccountLock = targetLockKey ? await db.collection('session_account_runtime_locks').findOne({ _id: targetLockKey, sessionId: targetSessionId, leaseUntil: { $gt: now } }, { projection: { _id: 1, owner: 1 } }) : null;
    if (!targetAccountLock) return { retired: false, reason: 'target_account_runtime_lock_not_held' };
    const sourceRuntimeLock = await db.collection('session_runtime_locks').findOne({ _id: sourceSessionId, leaseUntil: { $gt: now } }, { projection: { owner: 1, leaseUntil: 1 } });
    if (sourceRuntimeLock && sourceRuntimeLock.owner !== processInstanceId) return { retired: false, reason: 'source_runtime_owned_by_another_instance' };
    const sourceAccountLock = await db.collection('session_account_runtime_locks').findOne({ sessionId: sourceSessionId, leaseUntil: { $gt: now } }, { projection: { owner: 1, _id: 1 } });
    if (sourceAccountLock && sourceAccountLock.owner !== processInstanceId) return { retired: false, reason: 'source_account_lock_owned_by_another_instance' };
    if (sourceRuntime?.sock) {
        const runtimePhone = getAuthenticatedPhoneNumber(sourceRuntime.sock.user, sourceRuntime.authState?.creds);
        const runtimeLid = getAuthenticatedLid(sourceRuntime.sock.user, sourceRuntime.authState?.creds);
        const runtimeMatches = !!((samePhone && runtimePhone === targetPhone) || (sameLid && runtimeLid === targetLid));
        if (!runtimeMatches) return { retired: false, reason: 'source_live_socket_identity_unverified' };
        const sourceSocketClosed = await closeSessionSocketWithoutAuthFlush(sourceSessionId, 'same_account_session_replaced', { status: 'duplicate_account', scheduleRetry: false });
        if (!sourceSocketClosed) return { retired: false, reason: 'source_socket_close_not_confirmed' };
    } else {
        const pendingReconnect = reconnectTimers.get(sourceSessionId);
        if (pendingReconnect) clearTimeout(pendingReconnect);
        reconnectTimers.delete(sourceSessionId);
        await releaseSessionRuntimeLock(sourceSessionId);
    }
    const duplicateAt = sourceOwner.duplicateAccountDetectedAt || now;
    await ownerCollection.updateOne(
        { sessionId: sourceSessionId },
        { $set: { connectionStatus: 'duplicate_account', duplicateAccountOf: targetSessionId, duplicateAccountDetectedAt: duplicateAt, duplicateAccountIdentityHash: shortLogHash(targetPhone || targetLid), duplicateAuthPreserved: true, reauthRequired: false, socketAuthenticated: false, socketReady: false, pairingPending: false, unconnectedSinceAt: duplicateAt, statusUpdatedAt: now, updatedAt: now } }
    );
    sessionOwnersCache.delete(sourceSessionId);
    const migrated = await mergeSessionScopedData(sourceSessionId, targetSessionId);
    if (!migrated?.migrated) return { retired: false, reason: migrated?.reason || 'session_settings_migration_failed' };
    await deleteMongoSession(sourceSessionId);
    console.warn('[session-account-duplicate-retired]', { sourceSessionId, targetSessionId, reason, samePhone, sameLid, migratedGroupSettings: migrated.groupSettings, migratedDel2Targets: migrated.del2Targets, migratedDel3Rules: migrated.del3Rules, migratedLidPhoneMappings: migrated.lidPhoneMappings, oldAuthDocumentsDeleted: true, targetSignalCredentialsPreserved: true });
    return { retired: true, migrated };
}

async function consolidateDuplicateSessionsForAccount(targetSessionId, user, creds) {
    if (!db || !targetSessionId) return 0;
    const phone = getAuthenticatedPhoneNumber(user, creds);
    const lid = getAuthenticatedLid(user, creds);
    const clauses = [];
    if (phone) clauses.push({ Number: phone }, { number: phone }, { PairingNumber: phone }, { AccountJid: `${phone}@s.whatsapp.net` }, { accountJid: `${phone}@s.whatsapp.net` });
    if (lid) clauses.push({ OwnerLid: lid }, { ownerLid: lid }, { AccountJid: lid }, { accountJid: lid });
    if (!clauses.length) return 0;
    const owners = await db.collection('session_owners').find({ sessionId: { $ne: targetSessionId }, $or: clauses }).limit(100).toArray();
    let retired = 0;
    for (const owner of owners) {
        const sourceSessionId = String(owner.sessionId || '');
        if (!sourceSessionId || sourceSessionId === targetSessionId) continue;
        const sourceNumber = normalizePhoneNumber(owner.Number || owner.number || owner.PairingNumber || '') || getAuthenticatedPhoneNumber({ id: owner.AccountJid || owner.accountJid || '' }, null);
        const sourceJid = String(owner.AccountJid || owner.accountJid || '').trim();
        const sourceLid = normalizeLidCacheKey(owner.OwnerLid || owner.ownerLid || sourceJid);
        const sameIdentity = !!((phone && sourceNumber === phone) || (lid && sourceLid === lid));
        if (!sameIdentity) continue;
        const result = await retireDuplicateAccountSession(sourceSessionId, targetSessionId, 'authenticated_connection_open_replaced_previous_session').catch(error => {
            console.error('[session-account-duplicate-retirement-failed]', { sourceSessionId, targetSessionId, error: error?.message || String(error) });
            return { retired: false, reason: error?.message || 'retirement_failed' };
        });
        if (result?.retired) retired++;
        else console.warn('[session-account-duplicate-retirement-deferred]', { sourceSessionId, targetSessionId, reason: result?.reason || 'unknown' });
    }
    return retired;
}

async function getGroupSetting(sessionId, gjid, key) {
    const cacheKey = `${sessionId}_${gjid}_${key}`;
    if (groupSettingsCache.has(cacheKey)) {
        const cachedValue = groupSettingsCache.get(cacheKey);
        setBoundedMapEntry(groupSettingsCache, cacheKey, cachedValue, GROUP_SETTINGS_CACHE_MAX_ENTRIES);
        return cachedValue;
    }
    try {
        const doc = await db.collection('group_settings').findOne({ sessionId, gjid });
        const val = doc ? doc[key] : null;
        setBoundedMapEntry(groupSettingsCache, cacheKey, val, GROUP_SETTINGS_CACHE_MAX_ENTRIES);
        return val;
    } catch (error) {
        console.error('[group-setting-read-failed]', { sessionId, group: gjid, setting: key, error: error?.message || String(error) });
        return null;
    }
}

async function setGroupSetting(sessionId, gjid, key, value) {
    const cacheKey = `${sessionId}_${gjid}_${key}`;
    await db.collection('group_settings').updateOne({ sessionId, gjid }, { $set: { [key]: value } }, { upsert: true });
    setBoundedMapEntry(groupSettingsCache, cacheKey, value, GROUP_SETTINGS_CACHE_MAX_ENTRIES);
}

async function getDel2Targets(sessionId, gjid) {
    const cacheKey = `${sessionId}_${gjid}`;
    if (activeDel2UsersCache.has(cacheKey)) return activeDel2UsersCache.get(cacheKey);
    try {
        const col = db.collection('group_del2');
        const docs = await col.find({ sessionId, gjid }).toArray();
        const list = docs.map(d => d.targetJid);
        setBoundedMapEntry(activeDel2UsersCache, cacheKey, list, ACTIVE_DEL2_CACHE_MAX_ENTRIES);
        return list;
    } catch (error) {
        console.error('[del2-targets-read-failed]', { sessionId, group: gjid, error: error?.message || String(error) });
        throw error;
    }
}

async function addDel2Target(sessionId, gjid, targetJid) {
    try {
        const col = db.collection('group_del2');
        await col.updateOne({ sessionId, gjid, targetJid }, { $set: { active: true } }, { upsert: true });
        const current = await getDel2Targets(sessionId, gjid);
        if (!current.includes(targetJid)) {
            current.push(targetJid);
            setBoundedMapEntry(activeDel2UsersCache, `${sessionId}_${gjid}`, current, ACTIVE_DEL2_CACHE_MAX_ENTRIES);
        }
    } catch (error) {
        console.error('[del2-target-add-failed]', { sessionId, group: gjid, target: targetJid, error: error?.message || String(error) });
        throw error;
    }
}

async function removeDel2Target(sessionId, gjid, targetJid) {
    try {
        const col = db.collection('group_del2');
        await col.deleteMany({ sessionId, gjid, targetJid });
        const current = await getDel2Targets(sessionId, gjid);
        const index = current.indexOf(targetJid);
        if (index > -1) {
            current.splice(index, 1);
            setBoundedMapEntry(activeDel2UsersCache, `${sessionId}_${gjid}`, current, ACTIVE_DEL2_CACHE_MAX_ENTRIES);
        }
    } catch (error) {
        console.error('[del2-target-remove-failed]', { sessionId, group: gjid, target: targetJid, error: error?.message || String(error) });
        throw error;
    }
}

function getWhatsAppMessageFormat(value) {
    const source = value?.message && typeof value.message === 'object' ? value.message : value;
    const groups = {
        text: ['conversation', 'extendedTextMessage', 'buttonsResponseMessage', 'listResponseMessage', 'templateButtonReplyMessage', 'interactiveResponseMessage', 'groupMentionMessage', 'buttonsMessage', 'listMessage', 'templateMessage', 'interactiveMessage'],
        image: ['imageMessage'],
        video: ['videoMessage', 'ptvMessage'],
        audio: ['audioMessage', 'voiceMessage'],
        document: ['documentMessage'],
        sticker: ['stickerMessage', 'lottieStickerMessage'],
        album: ['albumMessage'],
        location: ['locationMessage', 'liveLocationMessage'],
        contact: ['contactMessage', 'contactsArrayMessage', 'phoneNumberShareMessage'],
        poll: ['pollCreationMessage', 'pollCreationMessageV2', 'pollCreationMessageV3', 'pollUpdateMessage'],
        reaction: ['reactionMessage'],
        event: ['eventMessage', 'scheduledCallCreationMessage', 'scheduledCallEditMessage'],
        status: ['groupStatusMessageContent', 'groupStatusMessage', 'groupStatusMessageV2', 'statusMessage', 'statusMentionMessage', 'statusMentionMessageV2', 'statusMentionMessageV2Extension', 'statusMentionMessageExtension'],
        group: ['groupInviteMessage', 'newsletterAdminInviteMessage'],
        commerce: ['productMessage', 'orderMessage', 'catalogMessage'],
        payment: ['paymentInviteMessage', 'requestPaymentMessage', 'sendPaymentMessage', 'declinePaymentRequestMessage', 'cancelPaymentRequestMessage'],
        call: ['callLogMessage']
    };
    const keyToFormat = new Map();
    for (const [format, keys] of Object.entries(groups)) for (const key of keys) keyToFormat.set(key, format);
    const mediaFormats = new Set(['image', 'video', 'audio', 'document', 'sticker', 'album']);
    const ignored = new Set(['messageContextInfo', 'senderKeyDistributionMessage', 'protocolMessage', 'keepInChatMessage', 'messageHistoryBundle', 'contextInfo', 'quotedMessage', 'deviceListMetadata', 'deviceListMetadataVersion', 'messageSecret', 'externalAdReply', 'thumbnail', 'jpegThumbnail']);
    const wrapperKeys = new Set(['ephemeralMessage', 'viewOnceMessage', 'viewOnceMessageV2', 'viewOnceMessageV2Extension', 'documentWithCaptionMessage', 'deviceSentMessage', 'editedMessage', 'associatedChildMessage', 'groupStatusMessageContent', 'statusMessage']);
    const viewOnceWrapperKeys = new Set(['viewOnceMessage', 'viewOnceMessageV2', 'viewOnceMessageV2Extension']);
    const getNested = payload => {
        if (!payload || typeof payload !== 'object') return null;
        if (payload.message && typeof payload.message === 'object') return payload.message;
        if (payload.content && typeof payload.content === 'object') return payload.content;
        if (payload.associatedChildMessage && typeof payload.associatedChildMessage === 'object') return payload.associatedChildMessage;
        return payload;
    };
    const scan = (node, depth, seen, inheritedViewOnce = false) => {
        if (!node || typeof node !== 'object' || depth > 18 || seen.has(node)) return '';
        seen.add(node);
        const entries = Object.entries(node);
        const nodeViewOnce = inheritedViewOnce || node.viewOnce === true || node.isViewOnce === true || node.is_view_once === true;
        for (const [key] of entries) {
            if (ignored.has(key)) continue;
            const known = keyToFormat.get(key);
            if (known === 'status') return 'status';
        }
        for (const [key, payload] of entries) {
            if (!viewOnceWrapperKeys.has(key) || !payload || typeof payload !== 'object') continue;
            const found = scan(getNested(payload), depth + 1, seen, true);
            if (found) return found;
        }
        for (const [key, payload] of entries) {
            if (!wrapperKeys.has(key) || viewOnceWrapperKeys.has(key) || !payload || typeof payload !== 'object') continue;
            const found = scan(getNested(payload), depth + 1, seen, nodeViewOnce);
            if (found) return found;
        }
        for (const [key, payload] of entries) {
            if (ignored.has(key) || wrapperKeys.has(key)) continue;
            const known = keyToFormat.get(key);
            if (!known) continue;
            const payloadViewOnce = payload && typeof payload === 'object' && (payload.viewOnce === true || payload.isViewOnce === true || payload.is_view_once === true);
            return known;
        }
        let fallback = '';
        for (const [key, payload] of entries) {
            if (ignored.has(key) || wrapperKeys.has(key) || !payload || typeof payload !== 'object') continue;
            const found = scan(payload, depth + 1, seen, nodeViewOnce);
            if (found && !found.startsWith('other:')) return found;
            if (found && !fallback) fallback = found;
            if (!found && !fallback) fallback = `other:${String(key).slice(0, 80)}`;
        }
        return fallback;
    };
    return scan(source, 0, new WeakSet());
}

function extractWhatsAppResendMedia(value) {
    const source = value?.message && typeof value.message === 'object' ? value.message : value;
    const wrapperKeys = new Set([
        'ephemeralMessage', 'viewOnceMessage', 'viewOnceMessageV2', 'viewOnceMessageV2Extension',
        'documentWithCaptionMessage', 'deviceSentMessage', 'editedMessage', 'associatedChildMessage',
        'groupStatusMessageContent', 'groupStatusMessage', 'groupStatusMessageV2', 'statusMessage',
        'statusMentionMessage', 'statusMentionMessageV2', 'statusMentionMessageV2Extension', 'statusMentionMessageExtension'
    ]);
    const viewOnceWrapperKeys = new Set(['viewOnceMessage', 'viewOnceMessageV2', 'viewOnceMessageV2Extension']);
    const ignoredKeys = new Set([
        'messageContextInfo', 'contextInfo', 'quotedMessage', 'senderKeyDistributionMessage',
        'protocolMessage', 'messageSecret', 'deviceListMetadata', 'deviceListMetadataVersion',
        'externalAdReply', 'thumbnail', 'jpegThumbnail'
    ]);
    const mediaTypes = {
        imageMessage: { type: 'image', downloadType: 'image', sendType: 'image' },
        videoMessage: { type: 'video', downloadType: 'video', sendType: 'video' },
        ptvMessage: { type: 'video', downloadType: 'video', sendType: 'video' },
        audioMessage: { type: 'audio', downloadType: 'audio', sendType: 'audio' },
        voiceMessage: { type: 'audio', downloadType: 'audio', sendType: 'audio', ptt: true },
        documentMessage: { type: 'document', downloadType: 'document', sendType: 'document' },
        stickerMessage: { type: 'sticker', downloadType: 'sticker', sendType: 'sticker' },
        lottieStickerMessage: { type: 'sticker', downloadType: 'sticker', sendType: 'sticker' }
    };
    const visit = (node, inheritedViewOnce, depth, seen) => {
        if (!node || typeof node !== 'object' || depth > 20 || seen.has(node)) return null;
        seen.add(node);
        const nodeViewOnce = inheritedViewOnce || node.viewOnce === true || node.isViewOnce === true || node.is_view_once === true;
        const entries = Object.entries(node);
        for (const [key, payload] of entries) {
            if (!wrapperKeys.has(key) || !payload || typeof payload !== 'object') continue;
            const nested = payload.message && typeof payload.message === 'object'
                ? payload.message
                : payload.content && typeof payload.content === 'object'
                    ? payload.content
                    : payload;
            const result = visit(nested, nodeViewOnce || viewOnceWrapperKeys.has(key), depth + 1, seen);
            if (result) return result;
        }
        for (const [key, payload] of entries) {
            const descriptor = mediaTypes[key];
            if (!descriptor || !payload || typeof payload !== 'object') continue;
            return {
                ...descriptor,
                payload,
                viewOnce: nodeViewOnce || payload.viewOnce === true || payload.isViewOnce === true || payload.is_view_once === true,
                sourceType: key
            };
        }
        for (const [key, payload] of entries) {
            if (ignoredKeys.has(key) || wrapperKeys.has(key) || !payload || typeof payload !== 'object') continue;
            const result = visit(payload, nodeViewOnce, depth + 1, seen);
            if (result) return result;
        }
        return null;
    };
    return visit(source, false, 0, new WeakSet());
}
async function findQuotedMessageForCommand(sessionId, chatJid, messageId, allowOutgoingLegacy = true) {
    const id = String(messageId || '').trim();
    const chat = String(chatJid || '').trim();
    if (!sessionId || !id) return null;
    const inMemory = recentMsgsCache.find(entry => {
        if (entry.sessionId !== sessionId || String(entry.id) !== id) return false;
        const aliases = [entry.from, ...(Array.isArray(entry.chatAliases) ? entry.chatAliases : []), entry.key?.remoteJidAlt].filter(Boolean);
        return !chat || aliases.some(alias => String(alias) === chat || areEquivalentWhatsAppChatJids(sessionId, alias, chat));
    });
    if (inMemory?.message) return { ...inMemory, source: 'session_memory' };
    if (!db) return null;
    try {
        const quoted = await db.collection('baileys_quoted_messages').findOne(
            { _id: `quoted:${sessionId}:${id}`, sessionId, messageId: id },
            { projection: { sessionId: 1, messageId: 1, remoteJid: 1, remoteJidAlt: 1, remoteJidAliases: 1, fromMe: 1, participant: 1, participantAlt: 1, participantPn: 1, senderPn: 1, key: 1, message: 1, messageFormat: 1, messageTimestamp: 1 } }
        );
        if (quoted && (quoted.message || quoted.messageFormat)) {
            const aliases = [quoted.remoteJid, quoted.remoteJidAlt, ...(Array.isArray(quoted.remoteJidAliases) ? quoted.remoteJidAliases : [])].filter(Boolean);
            if (!chat || aliases.some(alias => String(alias) === chat || areEquivalentWhatsAppChatJids(sessionId, alias, chat))) return { ...quoted, source: 'persistent_quoted_cache' };
        }
    } catch (error) {
        console.warn('[quoted-message-cache-read-failed]', { sessionId, messageId: id, error: error?.message || String(error) });
    }
    if (!allowOutgoingLegacy) return null;
    try {
        const legacy = await db.collection('baileys_outgoing_messages').findOne(
            { _id: `${sessionId}:${id}`, sessionId, messageId: id },
            { projection: { sessionId: 1, messageId: 1, remoteJid: 1, remoteJidAlt: 1, remoteJidAliases: 1, fromMe: 1, participant: 1, participantAlt: 1, participantPn: 1, senderPn: 1, message: 1, messageTimestamp: 1 } }
        );
        if (legacy?.message) {
            const aliases = [legacy.remoteJid, legacy.remoteJidAlt, ...(Array.isArray(legacy.remoteJidAliases) ? legacy.remoteJidAliases : [])].filter(Boolean);
            if (!chat || !aliases.length || aliases.some(alias => String(alias) === chat || areEquivalentWhatsAppChatJids(sessionId, alias, chat))) return { ...legacy, source: 'legacy_outgoing_cache' };
        }
    } catch (error) {
        console.warn('[quoted-message-legacy-read-failed]', { sessionId, messageId: id, error: error?.message || String(error) });
    }
    return null;
}

async function getDel3Rules(sessionId, gjid) {
    const cacheKey = `${sessionId}_${gjid}`;
    if (activeDel3RulesCache.has(cacheKey)) return activeDel3RulesCache.get(cacheKey);
    if (!db) return [];
    const docs = await db.collection('group_del3').find({ sessionId, gjid, active: true }).toArray();
    const rules = docs.map(doc => ({ format: String(doc.messageFormat || '').trim(), sampleText: doc.sampleText || '', activatedAt: doc.activatedAt || doc.updatedAt || doc.createdAt || null })).filter(rule => rule.format);
    setBoundedMapEntry(activeDel3RulesCache, cacheKey, rules, ACTIVE_DEL2_CACHE_MAX_ENTRIES);
    return rules;
}

async function stageDel3Rule(sessionId, gjid, messageFormat, sampleText) {
    if (!db) throw new Error('del3_database_unavailable');
    const now = new Date();
    await db.collection('group_del3').updateOne(
        { sessionId, gjid, messageFormat },
        { $set: { active: false, activationPending: true, sampleText: String(sampleText || '').slice(0, 500), pendingAt: now, updatedAt: now }, $setOnInsert: { createdAt: now } },
        { upsert: true }
    );
    activeDel3RulesCache.delete(`${sessionId}_${gjid}`);
    return now;
}

async function activateDel3Rule(sessionId, gjid, messageFormat) {
    if (!db) throw new Error('del3_database_unavailable');
    const activatedAt = new Date();
    const result = await db.collection('group_del3').updateOne(
        { sessionId, gjid, messageFormat, activationPending: true },
        { $set: { active: true, activatedAt, updatedAt: activatedAt }, $unset: { activationPending: '', pendingAt: '' } }
    );
    if (!result || Number(result.matchedCount || 0) !== 1) throw new Error('del3_pending_rule_not_found');
    activeDel3RulesCache.delete(`${sessionId}_${gjid}`);
    const docs = await db.collection('group_del3').find({ sessionId, gjid, active: true }).toArray();
    const rules = docs.map(doc => ({ format: String(doc.messageFormat || '').trim(), sampleText: doc.sampleText || '', activatedAt: doc.activatedAt || doc.updatedAt || doc.createdAt || null })).filter(rule => rule.format);
    setBoundedMapEntry(activeDel3RulesCache, `${sessionId}_${gjid}`, rules, ACTIVE_DEL2_CACHE_MAX_ENTRIES);
    return activatedAt;
}

async function discardPendingDel3Rule(sessionId, gjid, messageFormat) {
    if (db) await db.collection('group_del3').deleteMany({ sessionId, gjid, messageFormat, activationPending: true });
    activeDel3RulesCache.delete(`${sessionId}_${gjid}`);
}

async function removeDel3Rule(sessionId, gjid, messageFormat) {
    if (db) await db.collection('group_del3').deleteMany({ sessionId, gjid, messageFormat });
    activeDel3RulesCache.delete(`${sessionId}_${gjid}`);
    return getDel3Rules(sessionId, gjid);
}

async function applyDel3ToIncomingMessage(sock, sessionId, message, groupJid, senderJid, senderAliases, ownerRecord, canBotModerateGroupFn, isProtectedWhatsAppTargetFn) {
    const chat = String(groupJid || message?.key?.remoteJid || '').trim();
    const messageId = String(message?.key?.id || '').trim();
    if (!/@g\.us$/i.test(chat) || !messageId || message?.key?.fromMe === true) return false;
    const format = getWhatsAppMessageFormat(message);
    if (!format) return false;
    const rules = await getDel3Rules(sessionId, chat);
    const matchingRule = rules.find(rule => rule.format === format);
    if (!matchingRule) return false;
    if (typeof canBotModerateGroupFn === 'function' && !await canBotModerateGroupFn(chat)) {
        console.warn('[del3-skip-bot-permission-unavailable]', { sessionId, group: chat, messageId, format });
        return false;
    }
    const ownerIdentityAvailable = !!(ownerRecord && typeof ownerRecord === 'object' && [ownerRecord.Number, ownerRecord.number, ownerRecord.OwnerNumber, ownerRecord.ownerNumber, ownerRecord.PairingNumber, ownerRecord.AccountJid, ownerRecord.accountJid, ownerRecord.OwnerLid, ownerRecord.ownerLid].some(value => String(value || '').trim()));
    if (!ownerIdentityAvailable) {
        console.warn('[del3-message-protected]', { sessionId, group: chat, messageId, format, reason: 'owner_identity_record_unavailable_fail_closed' });
        return false;
    }
    const aliasText = (Array.isArray(senderAliases) ? senderAliases : []).map(String).join(' ');
    if (typeof isProtectedWhatsAppTargetFn === 'function' && isProtectedWhatsAppTargetFn(senderJid, ownerRecord, sock?.user?.id || '', aliasText)) {
        console.info('[del3-message-protected]', { sessionId, group: chat, messageId, format, reason: 'host_or_bot' });
        return false;
    }
    const timestampRaw = message?.messageTimestamp && typeof message.messageTimestamp.toNumber === 'function' ? message.messageTimestamp.toNumber() : message?.messageTimestamp;
    const timestamp = Number(timestampRaw) || 0;
    const messageTimestampMs = timestamp > 0 ? (timestamp < 1000000000000 ? timestamp * 1000 : timestamp) : 0;
    const activatedAtMs = matchingRule.activatedAt ? new Date(matchingRule.activatedAt).getTime() : 0;
    if (messageTimestampMs > 0 && activatedAtMs > 0 && messageTimestampMs < activatedAtMs - 5000) {
        console.info('[del3-message-skipped-before-activation]', { sessionId, group: chat, messageId, format, messageTimestampMs, activatedAtMs });
        return false;
    }
    console.info('[del3-live-delete-validation]', { sessionId, group: chat, messageId, format, action: 'attempt_delete_and_use_whatsapp_server_ack_as_authority' });
    const account = getAuthenticatedPhoneNumber(sock?.user, activeSessions.get(sessionId)?.authState?.creds) || getAuthenticatedLid(sock?.user, activeSessions.get(sessionId)?.authState?.creds) || sessionId;
    const dedupId = `del3:${shortLogHash(account)}:${chat}:${messageId}`;
    if (del3DeleteDedupCache.has(dedupId)) return false;
    let claimed = false;
    try {
        if (db) {
            const claim = await db.collection('processed_messages').updateOne(
                { _id: dedupId },
                { $setOnInsert: { sessionId, messageId, remoteJid: chat, operation: 'del3', ts: Date.now(), expireAt: new Date(Date.now() + PROCESSED_MESSAGE_RETENTION_MS) } },
                { upsert: true }
            );
            claimed = claim.upsertedCount === 1;
            if (!claimed) return false;
        } else claimed = true;
        del3DeleteDedupCache.set(dedupId, Date.now());
        while (del3DeleteDedupCache.size > 12000) del3DeleteDedupCache.delete(del3DeleteDedupCache.keys().next().value);
        const sourceKey = message.key || {};
        const participant = String(sourceKey.participant || sourceKey.participantPn || sourceKey.participantAlt || sourceKey.senderPn || senderJid || '').trim();
        const deleteKey = { ...sourceKey, remoteJid: String(sourceKey.remoteJid || chat), id: messageId, fromMe: sourceKey.fromMe === true };
        if (participant) deleteKey.participant = participant;
        const deleteResult = await queuedDeleteMessageWithAck(sock, chat, deleteKey, 180, 6500);
        console.info('[del3-message-format-matched]', { sessionId, group: chat, messageId, format, deleteRequestSent: true, serverAcknowledgementTracked: true, serverAcknowledged: true, acknowledgementStatus: deleteResult.acknowledgementStatus, scope: 'same_group_same_whatsapp_format' });
        return true;
    } catch (error) {
        if (claimed && db) await db.collection('processed_messages').deleteOne({ _id: dedupId }).catch(() => {});
        del3DeleteDedupCache.delete(dedupId);
        console.warn('[del3-message-delete-failed]', { sessionId, group: chat, messageId, format, error: error?.message || String(error) });
        return false;
    }
}

process.on('unhandledRejection', (error) => {
    const message = String(error?.message || error || '');
    const expectedClosedSocket = /^(?:Connection Closed|1006)$|WebSocket is not open|socket.*closed/i.test(message);
    if (expectedClosedSocket && (tfbotWorkerStopping || serverShuttingDown || workerDrainingSessionIds.size > 0 || Date.now() < workerDrainExpectedClosedUntil)) {
        console.warn('[baileys-closed-socket-rejection-during-handoff]', { error: message.slice(0, 120), workerStopping: tfbotWorkerStopping, drainingSessionCount: workerDrainingSessionIds.size, action: 'expected_transport_close_while_worker_handoff' });
        return;
    }
    if (expectedClosedSocket) {
        console.warn('[baileys-closed-socket-rejection]', { error: message.slice(0, 120), action: 'socket_closed_without_process_crash' });
        return;
    }
    console.error('[unhandledRejection]', error?.message || error);
});
process.on('uncaughtException', (error) => {
    const exceptionText = String(error?.message || error?.stack || error || 'unknown');
    if (/Failed to decrypt message with any known session|Bad MAC/i.test(exceptionText)) {
        console.warn('[whatsapp-signal] An individual message could not be decrypted; the bot remains online and stored auth data is preserved.');
        return;
    }
    console.error('[uncaughtException]', error?.stack || error?.message || error);
    process.exit(1);
});

