const MAX_WHATSAPP_CAPTION_CHARS = 950;

function normalizeCaptionText(value) {
    return String(value ?? '').replace(/\r\n?/g, '\n').trim();
}

function normalizeInfoText(value) {
    const source = Array.isArray(value) ? value.join('\n') : String(value ?? '');
    return source.replace(/\r\n?/g, '\n').replace(/\\+n/g, '\n').replace(/\\+r/g, '\r');
}

function hasWhatsAppFormatting(value) {
    const source = String(value || '');
    return /(^|\n)\s*>\s/m.test(source)
        || /\*_([\s\S]+?)_\*/.test(source)
        || /(?:^|[\s([{>])\*[^*\n]+\*(?=$|[\s.,;:!?)}\]])/m.test(source)
        || /(?:^|[\s([{>])_[^_\n]+_(?=$|[\s.,;:!?)}\]])/m.test(source)
        || /(?:^|[\s([{>])~[^~\n]+~(?=$|[\s.,;:!?)}\]])/m.test(source)
        || /```|`[^`\n]+`/.test(source);
}

function buildCaption(type, text, userName, preserveFormatting = null, ownerName = '') {
    const cleanType = String(type || 'Message').replace(/[\r\n]+/g, ' ').trim().slice(0, 48) || 'Message';
    const cleanText = normalizeCaptionText(text);
    const cleanUserName = (sanitizeSessionDisplayName(userName) || 'Inconnu').replace(/"/g, '');
    const cleanOwnerName = sanitizeSessionDisplayName(ownerName) || 'Compte connecté';
    const keepFormatting = typeof preserveFormatting === 'boolean' ? preserveFormatting : hasWhatsAppFormatting(cleanText);
    const content = cleanText ? (keepFormatting ? cleanText : `*_${cleanText}_*`) : '';
    return `*○ ${cleanType}*\n\n*Bot (tfbot)*\nUtilisateur : "${cleanUserName}"\nPropriétaire : ${cleanOwnerName}${content ? `\n\n${content}` : ''}\n\n> *Bot (tfbot)*`;
}

function splitCaptionBodies(type, text, userName, maxChars = MAX_WHATSAPP_CAPTION_CHARS, preserveFormatting = null, ownerName = '') {
    const cleanText = normalizeCaptionText(text);
    const keepFormatting = typeof preserveFormatting === 'boolean' ? preserveFormatting : hasWhatsAppFormatting(cleanText);
    if (!cleanText || buildCaption(type, cleanText, userName, keepFormatting, ownerName).length <= maxChars) return [cleanText];
    const shellLength = buildCaption(type, '', userName, keepFormatting, ownerName).length;
    const budget = Math.max(80, maxChars - shellLength - 2);
    const tokens = cleanText.match(/\S+\s*/g) || [cleanText];
    const bodies = [];
    let current = '';
    for (const token of tokens) {
        let remainder = token;
        while (remainder) {
            const candidate = current + remainder;
            if (candidate.length <= budget) {
                current = candidate;
                remainder = '';
            } else if (current.trim()) {
                bodies.push(current.trim());
                current = '';
            } else {
                bodies.push(remainder.slice(0, budget).trim());
                remainder = remainder.slice(budget).trimStart();
            }
        }
    }
    if (current.trim()) bodies.push(current.trim());
    return bodies.length ? bodies : [''];
}

async function normalizeOutgoingImageBuffer(imageBuffer) {
    if (Buffer.isBuffer(imageBuffer)) return imageBuffer.length ? imageBuffer : null;
    if (imageBuffer instanceof Uint8Array) return imageBuffer.length ? Buffer.from(imageBuffer.buffer, imageBuffer.byteOffset, imageBuffer.byteLength) : null;
    return null;
}

async function sendImageCaptioned(sock, jid, imageBuffer, type, text, userName, sendOptions = {}) {
    const deliveryImageBuffer = await normalizeOutgoingImageBuffer(imageBuffer);
    if (!deliveryImageBuffer) throw new Error('outgoing_image_buffer_unavailable');
    const preserveFormatting = sendOptions.preserveFormatting === true || hasWhatsAppFormatting(text);
    const ownerName = sanitizeSessionDisplayName(sendOptions.ownerName || sock?.user?.name || sock?.user?.notify || sock?.user?.verifiedName || '') || 'Compte connecté';
    const bodies = splitCaptionBodies(type, text, userName, MAX_WHATSAPP_CAPTION_CHARS, preserveFormatting, ownerName);
    let lastResult = null;
    for (const body of bodies) {
        const caption = buildCaption(type, body, userName, preserveFormatting, ownerName);
        const options = {};
        if (Array.isArray(sendOptions.mentions) && sendOptions.mentions.length) {
            options.mentions = sendOptions.mentions.filter(mention => body.includes(`@${String(mention).split('@')[0]}`));
        }
        try {
            lastResult = await queuedSendMessage(sock, jid, { image: deliveryImageBuffer, caption, ...options }, sendOptions.messageOptions || {}, 220);
        } catch (error) {
            console.error('[whatsapp-send]', { action: String(type || 'Message'), error: error?.message || String(error), imageBytes: deliveryImageBuffer.length });
            throw error;
        }
    }
    return lastResult;
}
const logoPath = path.join(__dirname, 'adamdh7.png');
let adamLogoBuffer = fs.existsSync(logoPath) ? fs.readFileSync(logoPath) : null;
async function inspectAdamLogo() {
    if (!Buffer.isBuffer(adamLogoBuffer) || !adamLogoBuffer.length) {
        console.warn('[logo-image-source-unavailable]');
        return false;
    }
    const isPng = adamLogoBuffer.length >= 8 && adamLogoBuffer.subarray(0, 8).equals(Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]));
    const isJpeg = adamLogoBuffer.length >= 3 && adamLogoBuffer[0] === 255 && adamLogoBuffer[1] === 216 && adamLogoBuffer[2] === 255;
    const detectedFormat = isPng ? 'png' : isJpeg ? 'jpeg' : 'unsupported';
    console.info('[logo-image-source-preserved]', { originalBytes: adamLogoBuffer.length, detectedFormat, fileExtension: path.extname(logoPath).toLowerCase() });
    if (detectedFormat === 'unsupported') console.warn('[logo-image-source-format-warning]', { originalBytes: adamLogoBuffer.length });
    return true;
}

