                                                        if (!verifiedIdentity || !hasAuthenticatedWhatsAppCredentials(tempState.creds, tempSock.user)) throw new Error('qr_authentication_not_persisted');
                                                        try { tempSock.ev.removeAllListeners(); } catch (listenerError) {}
